/* Original bilingual examples. Source: data/authoring/vocabulary-examples-v113.tsv. */
(() => {
 const examples = {"v-0b7cc46c-2ed7-11ef-a183-99ad05e145f0":[["霧の中に人の姿が見えた。","雾中出现了一个人影。"],["店の昔の姿は写真に残っている。","商店从前的模样留在了照片里。"]],"v-0be9d62e-2ed7-11ef-a183-99ad05e145f0":[["借りた本を元の棚に戻した。","我把借的书放回了原来的架子。"],["古い紙を元にして、再生紙を作った。","我们用废旧纸张做了再生纸。"]],"v-0b7e2e9c-2ed7-11ef-a183-99ad05e145f0":[["入口では係の者にお声がけください。","请在入口找工作人员。"],["この道を知る者は少なかった。","知道这条路的人很少。"]],"v-0c025b72-2ed7-11ef-a183-99ad05e145f0":[["ふたを開けた瞬間、甘い香りがした。","打开盖子的瞬间，一股甜香扑来。"],["橋の向こうに日が沈む瞬間を撮った。","我拍下了太阳在桥对面落下的瞬间。"]],"v-0b9914dc-2ed7-11ef-a183-99ad05e145f0":[["一体どこから風が入るのだろう。","风究竟是从哪儿吹进来的？"],["机の配置を一体どう変えればよいのか。","桌子到底该怎么摆才好？"]],"v-0b5cf6dc-2ed7-11ef-a183-99ad05e145f0":[["村では旅の安全を神に祈った。","村里人向神祈求旅途平安。"],["昔話には、山に住む神が出てくる。","旧故事里有一位住在山里的神。"]],"v-0b98fbbe-2ed7-11ef-a183-99ad05e145f0":[["風が止み、一瞬だけ波の音が消えた。","风停下来，浪声有一瞬间消失了。"],["一瞬の油断で荷物を落とした。","一时疏忽，我把东西掉了。"]],"v-0bb730ac-2ed7-11ef-a183-99ad05e145f0":[["子どもは流されないよう必死で枝をつかんだ。","孩子拼命抓住树枝，免得被冲走。"],["閉館に間に合うよう必死に坂を上った。","为了赶在闭馆前到达，我拼命爬坡。"]],"v-0bb8aac2-2ed7-11ef-a183-99ad05e145f0":[["古い照明が店の雰囲気を作っている。","旧灯具营造了店内氛围。"],["初めは堅い雰囲気だったが、話すうちに和んだ。","开始气氛拘谨，聊着聊着放松了。"]],"v-0ba2c84c-2ed7-11ef-a183-99ad05e145f0":[["見渡す限り、雪が積もっていた。","目之所及全是积雪。"],["時間の許す限り、記録を調べた。","在时间允许的范围内，我尽量查了记录。"]],"v-0c59fefe-2ed7-11ef-a183-99ad05e145f0":[["無事に帰ってきたことが何よりうれしい。","能平安回来，比什么都高兴。"],["この作業には何より根気が要る。","这项工作最需要耐心。"]],"v-0bbb455c-2ed7-11ef-a183-99ad05e145f0":[["友人は劇で船長の役を演じた。","朋友在戏里扮演船长。"],["私は二人を会わせる役を引き受けた。","我接下了安排两人见面的差事。"]],"v-0bc74aaa-2ed7-11ef-a183-99ad05e145f0":[["一枚の地図が彼の運命を変えた。","一张地图改变了他的命运。"],["小さな店の運命は、町の再開発に左右された。","小店的命运受到小镇再开发的影响。"]],"v-0c07f956-2ed7-11ef-a183-99ad05e145f0":[["一枚の板が三千円相当だと聞いた。","听说一块木板价值约三千日元。"],["山頂では相当強い風が吹いていた。","山顶的风相当大。"]],"v-0bfec6d8-2ed7-11ef-a183-99ad05e145f0":[["お帰りの際は、受付に札をお返しください。","回去时请把牌子还给接待处。"],["道具を選ぶ際に、重さも確かめた。","选工具时，我也确认了重量。"]],"v-0be4bdc4-2ed7-11ef-a183-99ad05e145f0":[["あれが港に通じる唯一の道だ。","那是通往港口的唯一道路。"],["この写真は当時を知る唯一の手掛かりだった。","这张照片是了解当年的唯一线索。"]],"v-0b8175f2-2ed7-11ef-a183-99ad05e145f0":[["世の中には、同じ道具を違う目的で使う人がいる。","世上有人拿同一件工具做不同的事。"],["祖父は世の中の変化を新聞で追っていた。","爷爷通过报纸关注社会变化。"]],"v-0c052316-2ed7-11ef-a183-99ad05e145f0":[["重い荷物を運んだあとで身体を休めた。","搬完重物后，我让身体歇了一会儿。"],["朝の散歩で身体が温まった。","早上散步，身子暖和了起来。"]],"v-0c38b21c-2ed7-11ef-a183-99ad05e145f0":[["両チームの戦いは最後まで接戦だった。","两队的较量到最后都很激烈。"],["この丘で起きた戦いについて資料を読んだ。","我读了有关发生在这座丘陵上的战斗的材料。"]],"v-0baf46c6-2ed7-11ef-a183-99ad05e145f0":[["雨に打たれて全身がぬれた。","被雨淋得全身湿透。"],["長い坂を上ると、全身が温かくなった。","爬过长坡后，全身暖起来了。"]],"v-0c04fa4e-2ed7-11ef-a183-99ad05e145f0":[["彼女は地図を真剣な顔で見つめた。","她一脸认真地盯着地图。"],["失敗した理由を真剣に考えた。","我认真思考了失败的原因。"]],"v-0b9fb71a-2ed7-11ef-a183-99ad05e145f0":[["港に巨大なクレーンが立っていた。","港口立着一台巨大的起重机。"],["巨大な岩をよけて道が曲がっている。","道路为了避开巨岩而转了个弯。"]],"v-0c239ac6-2ed7-11ef-a183-99ad05e145f0":[["枝の先が鋭いので手袋をした。","树枝尖端锋利，我戴了手套。"],["鋭い質問が出て、説明を付け加えた。","有人提出尖锐的问题，我就补充了说明。"]],"v-0baeec12-2ed7-11ef-a183-99ad05e145f0":[["先ほど、駅の出口でお会いしましたね。","刚才我们在车站出口见过吧。"],["先ほどお渡しした紙に、番号を書いてください。","请在刚才交给您的纸上写下号码。"]],"v-0bea6e22-2ed7-11ef-a183-99ad05e145f0":[["窓をわずかに開けると、涼しい風が入った。","把窗稍微打开一点，就吹进了凉风。"],["わずか三日で水位が大きく変わった。","短短三天，水位就有了很大变化。"]],"v-0b98eb9c-2ed7-11ef-a183-99ad05e145f0":[["感想を一言だけ聞かせてください。","请简短说一句感想。"],["友人の何気ない一言で、緊張が解けた。","朋友无意间的一句话缓解了我的紧张。"]],"v-0bbf05ac-2ed7-11ef-a183-99ad05e145f0":[["初対面同士でも、同じ町の話で盛り上がった。","即使是初次见面，聊起同一个镇子也很热络。"],["参加者同士で、道具を貸し借りした。","参与者相互借用工具。"]],"v-0b9a5f9a-2ed7-11ef-a183-99ad05e145f0":[["風のない穏やかな朝だった。","那是个无风而宁静的早晨。"],["祖父はどんな質問にも穏やかに答えた。","无论什么问题，爷爷都温和地回答。"]],"v-7e8c02f2-4b53-11f1-a630-0ddc817ad47e":[["箱の中央に仕切りを入れた。","我在箱子中央加了一块隔板。"],["広場の中央に古い時計台が立っている。","广场中央立着一座旧钟楼。"]],"v-0b8d5ebc-2ed7-11ef-a183-99ad05e145f0":[["彼女の初めての恋は、春の旅から始まった。","她的初恋始于一次春日旅行。"],["この小説は、遠く離れた二人の恋を描く。","这部小说描写了相隔很远的两人的恋情。"]],"v-0c73a0f2-2ed7-11ef-a183-99ad05e145f0":[["夜中の音の正体は、風で揺れる看板だった。","半夜那阵响动原来是风吹招牌发出的。"],["物語の最後で旅人の正体が明かされた。","故事最后揭开了旅人的真实身份。"]],"v-0bddd130-2ed7-11ef-a183-99ad05e145f0":[["この荷物を一人で運ぶのは不可能だ。","一个人不可能搬动这些行李。"],["道が閉鎖され、車での移動が不可能になった。","道路封闭，无法开车出行了。"]],"v-0c5c3944-2ed7-11ef-a183-99ad05e145f0":[["準備は完璧だと思ったのに、鍵を忘れた。","原以为准备得完美，结果忘了钥匙。"],["完璧を目指さず、まず一度作ってみる。","先不求完美，试着做一遍。"]],"v-0ba9cab6-2ed7-11ef-a183-99ad05e145f0":[["その日の出来事を帰宅後に書き留めた。","我回家后记下了当天发生的事。"],["思いがけない出来事に皆が足を止めた。","突然发生的事让大家停下了脚步。"]],"v-0bcc9c08-2ed7-11ef-a183-99ad05e145f0":[["見た目は同じでも、重さが違った。","外观看起来一样，重量却不同。"],["古い机の見た目を変えずに修理した。","我在保持旧桌外观的前提下修了它。"]],"v-0c6855c6-2ed7-11ef-a183-99ad05e145f0":[["足元がぬれていて、歩くには最悪だった。","脚下湿滑，实在不适合走路。"],["最悪の場合に備えて、帰りの切符を買った。","为应付最糟的情况，我买好了回程票。"]],"v-68046bae-679e-11ef-89c9-3b0955f1365d":[["祖母がこの世を去ってから、庭は兄が守っている。","奶奶离世后，院子一直由哥哥打理。"],["この世に同じ模様の石が二つあるだろうか。","世上会有两块纹路一样的石头吗？"]],"v-0c2fd96c-2ed7-11ef-a183-99ad05e145f0":[["時点の記録は、日付が分かるように整理した。","我们把时点的记录按能辨明日期的方式整理了。"],["後から時点を確認するため、関係する資料を残した。","为了以后能核实时点，我们留下了相关材料。"]],"v-0bbb9da4-2ed7-11ef-a183-99ad05e145f0":[["優秀な職人でも、初めは失敗を重ねたそうだ。","听说再优秀的工匠起初也反复失败。"],["彼はこの班で最も優秀な設計者だ。","他是这个小组最优秀的设计者。"]],"v-0bd3cd3e-2ed7-11ef-a183-99ad05e145f0":[["祖母は出発の前に神様に手を合わせた。","出发前，奶奶向神明合掌祈祷。"],["その職人は、地元で「木工の神様」と呼ばれている。","那位工匠在当地被称为“木工之神”。"]],"v-0c3c3a04-2ed7-11ef-a183-99ad05e145f0":[["地下の通路から地上へ出た。","我从地下通道走到了地面。"],["地上からは高い屋根の模様が見えなかった。","从地面看不到高屋顶的花纹。"]],"v-0be106c0-2ed7-11ef-a183-99ad05e145f0":[["彼女の返事で、もう一度試す勇気が出た。","她的回复让我鼓起了再试一次的勇气。"],["皆の前で間違いを認めるには勇気が要る。","在众人面前承认错误需要勇气。"]],"v-0bf4be72-2ed7-11ef-a183-99ad05e145f0":[["幼いころは夏休みが永遠に続くように思えた。","小时候觉得暑假仿佛会永远持续。"],["どんな道具も永遠には使えない。","再好的工具也不能永远用下去。"]],"v-0be8e82c-2ed7-11ef-a183-99ad05e145f0":[["反対を聞かず、工事を強引に進めた。","没有听取反对意见就强行推进工程。"],["強引な誘い方だったので、その場で断った。","对方邀约的方式太强势，我当场拒绝了。"]],"v-0ba15e26-2ed7-11ef-a183-99ad05e145f0":[["扉の隙間から細い光が漏れた。","一束细光从门缝漏了出来。"],["予定の隙間に、短い散歩をした。","我趁行程空隙出去走了一小会儿。"]],"v-0be3b30c-2ed7-11ef-a183-99ad05e145f0":[["この紙には特殊な加工が施されている。","这种纸经过了特殊加工。"],["古い機械は特殊な工具がないと開けられない。","没有专用工具就打不开这台老机器。"]],"v-0ba3b504-2ed7-11ef-a183-99ad05e145f0":[["転んだが、幸いけがはなかった。","虽然摔倒了，所幸没有受伤。"],["近くに店があったのが幸いだった。","幸好附近有一家店。"]],"v-0ca67216-2ed7-11ef-a183-99ad05e145f0":[["相手は圧倒的な速さで坂を駆け上がった。","对方以压倒性的速度跑上坡。"],["投票では賛成が圧倒的に多かった。","投票中赞成票占压倒性多数。"]],"v-0c0f83f6-2ed7-11ef-a183-99ad05e145f0":[["大雨による被害を地図にまとめた。","我们把暴雨造成的损害汇总到地图上。"],["被害が広がらないよう、早めに水を止めた。","为了不让损失扩大，我们早早关了水。"]],"v-0c3f1620-2ed7-11ef-a183-99ad05e145f0":[["機械の内部にほこりがたまっていた。","机器内部积了灰。"],["建物の内部は、案内人と一緒に回った。","我们跟着向导参观了建筑内部。"]],"v-0ba9124c-2ed7-11ef-a183-99ad05e145f0":[["子どもの集団が橋を渡ってきた。","一群孩子从桥上走了过来。"],["一人の動きが集団全体に伝わった。","一个人的动作传递到了整个集体。"]],"v-0bb170d6-2ed7-11ef-a183-99ad05e145f0":[["計画を三つの段階に分けた。","我们把计划分成了三个阶段。"],["この段階では、まだ材料を買わなくてよい。","现阶段还不用买材料。"]],"v-49aa5162-b061-11ef-b775-e7560ea47657":[["迷子の居場所を、駅員が突き止めた。","车站工作人员查明了走失孩子的位置。"],["図書室は私にとって、安心できる居場所だった。","图书室对我来说是个能安心待着的地方。"]],"v-0bc5d5f8-2ed7-11ef-a183-99ad05e145f0":[["できたところを褒めたら、弟のやる気が出た。","夸了弟弟做得好的部分，他有干劲了。"],["休みなしで続けると、かえってやる気を失う。","一点也不休息地做下去，反而会失去干劲。"]],"v-0ba8cff8-2ed7-11ef-a183-99ad05e145f0":[["現地で周辺の状態を調べ、気づいたことを地図に書き込んだ。","我在现场调查周边地区，并把注意到的事情标在地图上。"],["季節が変わってから、周辺の様子をもう一度見に行った。","换季以后，我又去看了一次周边地区的情况。"]],"v-0bab5426-2ed7-11ef-a183-99ad05e145f0":[["その方法が常識だと思い込んでいた。","我一直以为那种做法是常识。"],["同じ常識がどこでも通用するわけではない。","同样的常识未必到哪里都适用。"]],"v-691ccbb2-679e-11ef-89c9-3b0955f1365d":[["不思議な縁で、旅先で同じ人と再会した。","缘分真奇妙，我在旅途中又遇到了同一个人。"],["祖父との縁がきっかけで、この工房を知った。","因为和爷爷有交情，我才知道了这间工坊。"]],"v-0badb9c8-2ed7-11ef-a183-99ad05e145f0":[["変更は明日、正式に発表される。","变更将在明天正式公布。"],["この橋の正式な名称を地図で確かめた。","我在地图上核对了这座桥的正式名称。"]],"v-0be26b14-2ed7-11ef-a183-99ad05e145f0":[["妹の力強い一言で、もう一度挑戦する気になった。","妹妹一句有力的话，让我想再挑战一次。"],["波が高くても、漁師は力強く櫂をこいだ。","即使浪高，渔民仍有力地划着桨。"]],"v-0bcd6af2-2ed7-11ef-a183-99ad05e145f0":[["飲み物は好みに合わせて選べる。","饮料可以按喜好选择。"],["机の色は兄と私で好みが違う。","哥哥和我喜欢的桌子颜色不同。"]],"v-0bf8ab68-2ed7-11ef-a183-99ad05e145f0":[["寒さで少し風邪気味になった。","天气冷，我有点感冒。"],["暗い廊下で足音が聞こえ、気味が悪かった。","昏暗的走廊传来脚步声，让人觉得瘆得慌。"]],"v-0ba89e52-2ed7-11ef-a183-99ad05e145f0":[["小さな種を、深さがそろうように植えた。","我把小种子种下，尽量让深度一致。"],["あの短い返事が口論の種になった。","那句简短的回复成了争吵的由头。"]],"v-694f40ce-679e-11ef-89c9-3b0955f1365d":[["絵の中の影が不自然に見えた。","画中的影子看起来不自然。"],["翻訳を直し、不自然な語順を改めた。","我修改译文，改掉了不自然的语序。"]],"v-0c52a58c-2ed7-11ef-a183-99ad05e145f0":[["地図を読むときのポイントを三つ教わった。","我学到了看地图的三个要点。"],["買い物でたまったポイントを使った。","我用了购物积攒的积分。"]],"v-0ba9ee74-2ed7-11ef-a183-99ad05e145f0":[["準備は順調に進み、夕方には終わった。","准备工作进展顺利，傍晚就结束了。"],["山道の前半は順調だった。","山路的前半程走得很顺利。"]],"v-0bd02be8-2ed7-11ef-a183-99ad05e145f0":[["落ちていた鍵の持ち主を探した。","我找了找掉在地上的钥匙的主人。"],["持ち主の許可を得て、写真を展示した。","得到物主许可后，我们展出了照片。"]],"v-0bdf6ec8-2ed7-11ef-a183-99ad05e145f0":[["遠くから来た方々に地図を配った。","我把地图分给远道而来的各位。"],["会場では地元の方々の話を聞いた。","在会场，我听了当地各位的讲述。"]],"v-0bb809c8-2ed7-11ef-a183-99ad05e145f0":[["現地で付近の状態を調べ、気づいたことを地図に書き込んだ。","我在现场调查附近区域，并把注意到的事情标在地图上。"],["季節が変わってから、付近の様子をもう一度見に行った。","换季以后，我又去看了一次附近区域的情况。"]],"v-0c41f732-2ed7-11ef-a183-99ad05e145f0":[["連絡先が不明なので、手紙を送れなかった。","联系方式不明，信没能寄出去。"],["この箱がいつ作られたかは不明だ。","这个盒子是什么时候做的还不清楚。"]],"v-0bb8677e-2ed7-11ef-a183-99ad05e145f0":[["この場所から眺める風景が好きで、何度も足を運んだ。","我喜欢从这里看到的风景，去了好几次。"],["古い写真に写る風景と、今の景色を比べてみた。","我把老照片里的风景和如今的景色作了比较。"]],"v-0c5740ce-2ed7-11ef-a183-99ad05e145f0":[["雪が庭一面を覆った。","雪覆盖了整个院子。"],["橋の開通は新聞の一面に載った。","大桥通车登上了报纸头版。"]],"v-0c1534d6-2ed7-11ef-a183-99ad05e145f0":[["細い糸を暗い所で結ぶのは容易ではない。","在暗处系细线并不容易。"],["新しい留め具なら、子どもでも容易に外せる。","新扣件连孩子也能轻松解开。"]],"v-0b9822c0-2ed7-11ef-a183-99ad05e145f0":[["風が止むと船の動きが安定した。","风停了，船的运动稳定下来。"],["回線が安定しないため、別の部屋で作業した。","因为网络不稳定，我换了一间房工作。"]],"v-0c10016e-2ed7-11ef-a183-99ad05e145f0":[["この店のパンは近所で評判がよい。","这家店的面包在附近口碑很好。"],["評判を聞いて、休日に展示を見に行った。","听说评价不错，我休息日去看了展览。"]],"v-0bab43dc-2ed7-11ef-a183-99ad05e145f0":[["映画の最後の場面を何度も見直した。","我反复重看了电影最后一幕。"],["急な変更が必要な場面では、この手順を使う。","遇到需要紧急变更的场合，就用这个流程。"]],"v-0bd23a50-2ed7-11ef-a183-99ad05e145f0":[["あの旅での出会いが、今の仕事につながった。","那次旅行中的相遇促成了如今的工作。"],["祖父は友人との出会いを日記に書いていた。","爷爷把与朋友相识的经过写在了日记里。"]],"v-0c6fc522-2ed7-11ef-a183-99ad05e145f0":[["当日の詳細は、後で紙にまとめて渡す。","当天的细节稍后会整理在纸上交给大家。"],["詳細な地図があるので、細い道も分かる。","有详细地图，连小路也找得到。"]],"v-0c5d1db4-2ed7-11ef-a183-99ad05e145f0":[["肝心の鍵が見つからず、出発できない。","最重要的钥匙没找到，出发不了。"],["時間よりも、全員が安全に戻ることが肝心だ。","最重要的是所有人平安回来，时间倒在其次。"]],"v-0b7ca360-2ed7-11ef-a183-99ad05e145f0":[["一枚の絵葉書が旅の始まりだった。","一张明信片是那次旅行的开端。"],["春の始まりを告げる花が咲いた。","报春的花开了。"]],"v-ebe732fe-181e-11f0-abeb-8bac7eec60c9":[["初めての引っ越しで、精神的な負担が大きかった。","第一次搬家，精神压力很大。"],["失敗が続いたので、精神的にも疲れた。","接连失败，心里也觉得累。"]],"v-0c398e12-2ed7-11ef-a183-99ad05e145f0":[["二つの家の争いは、境の位置から始まった。","两户人的纠纷始于分界线的位置。"],["争いを避けるために、条件を書面で決めた。","为避免争执，我们以书面确定了条件。"]],"v-0c3dfe34-2ed7-11ef-a183-99ad05e145f0":[["当初の予定では、今日中に橋を渡るはずだった。","按原定计划，本该在今天之内过桥。"],["初日に集めた人数は当初の見込みより少なかった。","首日参加人数少于原先预期。"]],"v-0c3a6bf2-2ed7-11ef-a183-99ad05e145f0":[["多数の人が徒歩で会場に来た。","许多人步行来到了会场。"],["会議では賛成が多数だった。","会上赞成者占多数。"]],"v-0c78d72a-2ed7-11ef-a183-99ad05e145f0":[["彼は壁を取り除く大胆な案を出した。","他大胆提出拆掉墙壁。"],["布を大胆に切って、形を大きく変えた。","我大胆裁剪布料，大幅改变了形状。"]],"v-0ba7c66c-2ed7-11ef-a183-99ad05e145f0":[["材料の質が違うと仕上がりも変わる。","材料质量不同，成品效果也会变。"],["記事の数より一つ一つの質を大切にした。","比起文章数量，我更重视每篇的质量。"]],"v-0bd94944-2ed7-11ef-a183-99ad05e145f0":[["祖父は長年、同じ庭の手入れをしてきた。","爷爷多年来一直打理同一座院子。"],["長年の疑問が、古い写真一枚で解けた。","一张老照片解开了多年的疑问。"]],"v-6cd262ba-b061-11ef-b775-e7560ea47657":[["工事の音は一時的なものだった。","施工噪声只是暂时的。"],["雨のため、渡し船は一時的に止まった。","渡船因雨暂时停运。"]],"v-0beac160-2ed7-11ef-a183-99ad05e145f0":[["砂糖が湿気で一つの塊になった。","糖受潮结成了一大块。"],["遠くからは、鳥の群れが黒い塊に見えた。","从远处看，鸟群像一团黑影。"]],"v-0cc2ff08-2ed7-11ef-a183-99ad05e145f0":[["彼は町で最強の棋士だと呼ばれている。","他被称为镇上最强的棋手。"],["今季最強と評されたチームにも弱点があった。","被评为本赛季最强的队伍也有弱点。"]],"v-0c056470-2ed7-11ef-a183-99ad05e145f0":[["展示では、人類が使った古い道具を紹介した。","展览介绍了人类使用过的古老工具。"],["文字の発明は人類の暮らしを大きく変えた。","文字的发明大大改变了人类生活。"]],"v-0c843304-2ed7-11ef-a183-99ad05e145f0":[["不意に戸が開き、外の光が差した。","门突然打开，外面的光照了进来。"],["後ろから名前を呼ばれて不意を突かれた。","身后有人叫我名字，我猝不及防。"]],"v-0cf9ef18-2ed7-11ef-a183-99ad05e145f0":[["家を出た途端、強い雨が降った。","刚一出门，就下起了大雨。"],["名前を聞いた途端、昔のことを思い出した。","一听到名字，我就想起了往事。"]],"v-0beefc9e-2ed7-11ef-a183-99ad05e145f0":[["予約のシステムを更新した。","我们更新了预约系统。"],["古いシステムでは、同じ情報を二度入力する必要があった。","旧系统里，同样的信息要录入两遍。"]],"v-0bbd9c1c-2ed7-11ef-a183-99ad05e145f0":[["曖昧な返事では、何時に行けばよいか分からない。","答复含糊，我不知道该几点去。"],["「早め」の意味が曖昧なので、時刻を書き足した。","“早点”的意思不明确，我补上了具体时间。"]],"v-0ca2b630-2ed7-11ef-a183-99ad05e145f0":[["彼女は町の祭りで「ミス港」に選ばれた。","她在镇上庆典中当选“港口小姐”。"],["昔の新聞に、初代ミスの写真が載っていた。","旧报上刊有首届选美冠军的照片。"]],"v-0c06f7f4-2ed7-11ef-a183-99ad05e145f0":[["棒の先端に赤い印を付けた。","我在杆的尖端做了个红记号。"],["列車の先端が橋の向こうに消えた。","列车头部消失在桥的另一边。"]],"v-0c19bfc4-2ed7-11ef-a183-99ad05e145f0":[["塩はいい加減な量ではなく、きちんと量った。","盐没有随便放，我认真称了。"],["いい加減に話を切り上げて、先に進もう。","聊到差不多就停，继续下一项吧。"]],"v-49aaf9e6-b061-11ef-b775-e7560ea47657":[["放課後、図書室で友人と待ち合わせた。","放学后，我和朋友约在图书室见。"],["放課後に残って舞台を片付けた。","放学后我们留下来收拾了舞台。"]],"v-0bfc8bc0-2ed7-11ef-a183-99ad05e145f0":[["会場の候補を三つに絞った。","我们把会场候选缩小到三个。"],["二人の候補から、話し合いで担当を選んだ。","我们商量后，从两名候选人里选出了负责人。"]],"v-0be41c0c-2ed7-11ef-a183-99ad05e145f0":[["鳥の羽が一枚、石の上に落ちていた。","一根鸟羽落在石头上。"],["扇風機の羽にほこりがたまった。","电风扇的叶片积了灰。"]],"v-0c88d012-2ed7-11ef-a183-99ad05e145f0":[["友人は別れ際に本音を話した。","朋友分别时说了心里话。"],["笑っていたが、本音では続けたいと思っていた。","我虽然笑着，心里其实想继续。"]],"v-0bcaa1f0-2ed7-11ef-a183-99ad05e145f0":[["妹は手先が器用で、小さな箱を作るのが上手だ。","妹妹手巧，擅长做小盒子。"],["彼は狭い隙間から器用に鍵を取り出した。","他灵巧地从窄缝里取出了钥匙。"]],"v-0c0778a0-2ed7-11ef-a183-99ad05e145f0":[["素人にも分かるように専門用語を減らした。","为让外行也能懂，我们减少了术语。"],["素人の私でも、二回目には形を作れた。","即使是外行的我，第二次也做出了形状。"]],"v-0b98f3b2-2ed7-11ef-a183-99ad05e145f0":[["味を確かめるため、一口だけ飲んだ。","为确认味道，我只喝了一口。"],["一口に雪といっても、降り方はいろいろだ。","虽统称为雪，下起来却有各种各样的情形。"]],"v-0c2af96a-2ed7-11ef-a183-99ad05e145f0":[["砂の上に水があるように見えたが、幻だった。","看似沙地上有水，原来是幻象。"],["霧の中の人影は、近づくと幻のように消えた。","雾中人影走近便如幻影般消失了。"]],"v-0c650d44-2ed7-11ef-a183-99ad05e145f0":[["一人で暮らし始めて、夜に孤独を感じた。","开始独居后，我夜里感到孤单。"],["長い旅では、孤独な時間を日記に書いた。","漫长旅途中，我把孤独的时刻写进了日记。"]],"v-0be78806-2ed7-11ef-a183-99ad05e145f0":[["雨の前に帰れたのは幸運だった。","能在下雨前回来真幸运。"],["幸運にも、探していた写真が二枚見つかった。","幸运的是，要找的照片找到了两张。"]],"v-0c88f8f8-2ed7-11ef-a183-99ad05e145f0":[["鳥は本能で、巣に近づくものを警戒する。","鸟会本能地警惕靠近鸟巢的东西。"],["大きな音に、とっさに身を伏せたのは本能だった。","听到巨响就立刻趴下，那是本能反应。"]],"v-0bf7ca0e-2ed7-11ef-a183-99ad05e145f0":[["勘に頼らず、何度も寸法を測った。","我没有靠直觉，而是反复量尺寸。"],["雨が来そうだという勘が当たった。","我觉得要下雨，直觉应验了。"]],"v-0bb9a076-2ed7-11ef-a183-99ad05e145f0":[["駅の案内で海岸方面のバスを探した。","我在车站指引中寻找开往海岸方向的公交。"],["叔父は出版方面の仕事に詳しい。","叔叔熟悉出版方面的工作。"]],"v-0bcba7d0-2ed7-11ef-a183-99ad05e145f0":[["昔の作り方と今の作り方の違いが興味深い。","过去和现在的制作方式有趣地不同。"],["この写真には興味深い手掛かりがある。","这张照片里有条耐人寻味的线索。"]],"v-0bdac21a-2ed7-11ef-a183-99ad05e145f0":[["水は透明で、底の砂まで見えた。","水很透明，连底下的沙都能看见。"],["中身が分かるよう、透明な袋に入れた。","为了看得见内容物，我装进了透明袋。"]],"v-0cabe9e4-2ed7-11ef-a183-99ad05e145f0":[["作業を止めたのには、何らかの理由があるはずだ。","停工应该有什么原因。"],["遅れる場合は、何らかの形で知らせてください。","如果会晚到，请想办法告知。"]],"v-0c444938-2ed7-11ef-a183-99ad05e145f0":[["暴力で問題を解決しようとしてはいけない。","不能试图用暴力解决问题。"],["物語では、主人公が暴力に反対する。","故事里，主人公反对暴力。"]],"v-0c6f68d4-2ed7-11ef-a183-99ad05e145f0":[["小柄な父でも、狭い戸口では肩が当たった。","即使爸爸个子小，在窄门口也撞到了肩。"],["その鳥は小柄だが、鳴き声がよく響く。","那只鸟体形虽小，叫声却很响亮。"]],"v-0bfc4a84-2ed7-11ef-a183-99ad05e145f0":[["古い橋を直した仕事に誇りを持っている。","我为修复旧桥的工作自豪。"],["祖母にとって、続けてきた店は誇りだった。","对奶奶来说，一直经营下来的店是她的骄傲。"]],"v-0c04d12c-2ed7-11ef-a183-99ad05e145f0":[["深夜になってようやく風がやんだ。","直到深夜风才停。"],["深夜の駅には、明かりが一つ残っていた。","深夜的车站还留着一盏灯。"]],"v-0c788c5c-2ed7-11ef-a183-99ad05e145f0":[["少し遅れただけなのに、大げさに謝られた。","只迟到了一点，对方却郑重其事地道了歉。"],["大げさに聞こえるが、あの一言に救われた。","听起来夸张，但那一句话帮了我。"]],"v-0baba868-2ed7-11ef-a183-99ad05e145f0":[["子どもたちはいろいろな職業の話を聞いた。","孩子们听了有关各种职业的介绍。"],["その職業を選んだ理由を本人に尋ねた。","我问了本人选择那个职业的原因。"]],"v-0bdda7dc-2ed7-11ef-a183-99ad05e145f0":[["この装置は温度の変化に敏感だ。","这台装置对温度变化敏感。"],["子どもは親の声の調子に敏感だった。","孩子对父母的语气很敏感。"]],"v-0cf3ec58-2ed7-11ef-a183-99ad05e145f0":[["似た容姿の二人を、声で見分けた。","我凭声音分辨了两个长相相似的人。"],["その画家は、容姿より表情を大切に描いた。","那位画家更重视描绘神态，外貌倒在其次。"]],"v-0ba4a82e-2ed7-11ef-a183-99ad05e145f0":[["新しい制度が国民の生活に影響した。","新制度影响了国民生活。"],["国民の意見を聞くため、公開の場が設けられた。","为了听取国民意见，设立了公开场合。"]],"v-0c399e70-2ed7-11ef-a183-99ad05e145f0":[["この仕事にふさわしい道具を選んだ。","我选了适合这项工作的工具。"],["式にふさわしい落ち着いた色の服を着た。","我穿了颜色沉稳、适合典礼的衣服。"]],"v-0bc2854c-2ed7-11ef-a183-99ad05e145f0":[["説明をシンプルにして図を一つに絞った。","我简化说明，只留一幅图。"],["構造がシンプルなので、掃除しやすい。","结构简单，所以容易清理。"]],"v-0be67f4c-2ed7-11ef-a183-99ad05e145f0":[["紙を折って作れる形は無限に思えた。","用纸折出来的形状似乎无穷无尽。"],["直線は両側に無限に延びると考える。","我们把直线看作向两端无限延伸。"]],"v-0be19860-2ed7-11ef-a183-99ad05e145f0":[["用件だけを短く書いて送った。","我只把要交代的事简短写下发了出去。"],["窓口で用件を尋ねられた。","窗口人员问我有什么事。"]],"v-0ba2af06-2ed7-11ef-a183-99ad05e145f0":[["この建物には古い技法と現代の技術が使われている。","这栋建筑既用了古老技法，也用了现代技术。"],["現代の地図には、もうこの道は載っていない。","现代地图上已不再标这条路。"]],"v-0bbbb6cc-2ed7-11ef-a183-99ad05e145f0":[["この券は発行日から一か月間有効だ。","这张券自出票日起一个月内有效。"],["日差しを遮るには、窓の外に布を掛けるのが有効だ。","想挡阳光，在窗外挂块布很有效。"]],"v-6cd34702-b061-11ef-b775-e7560ea47657":[["朝の静かなうちに目的地へ向かった。","趁早上安静，我朝目的地出发。"],["撮影した写真を見返すと、夕方の目的地は朝とは違って見えた。","回看照片时，我发现傍晚的目的地看起来与清晨不同。"]],"v-0c083f9c-2ed7-11ef-a183-99ad05e145f0":[["広場の中央に、船を造った人の像がある。","广场中央有造船者的雕像。"],["水面に街灯の像がゆらゆら映っていた。","水面上晃动着路灯的倒影。"]],"v-0be0b134-2ed7-11ef-a183-99ad05e145f0":[["この場所から眺める夜空が好きで、何度も足を運んだ。","我喜欢从这里看到的夜空，去了好几次。"],["古い写真に写る夜空と、今の景色を比べてみた。","我把老照片里的夜空和如今的景色作了比较。"]],"v-0bc80580-2ed7-11ef-a183-99ad05e145f0":[["何事かと思って窓を開けた。","我想是出了什么事，便打开了窗。"],["失敗したのに、彼は何事もなかったように話した。","明明失败了，他却若无其事地讲话。"]],"v-79b0ded2-679e-11ef-89c9-3b0955f1365d":[["点検済みの箱には青い札を付けた。","已检查的箱子贴上了蓝色标签。"],["この申込みはすでに手続き済みです。","这项申请已办完手续。"]],"v-0ba2507e-2ed7-11ef-a183-99ad05e145f0":[["あの犬は賢くて、一度で道を覚えた。","那条狗很聪明，只走一次就记住了路。"],["少ない材料を賢く使い、足りない分を補った。","我巧妙利用有限的材料，补上了不足的部分。"]],"v-0bb4dda2-2ed7-11ef-a183-99ad05e145f0":[["この村では独特の編み方で籠を作る。","这个村用独特的编法制篮。"],["川辺には雨上がりの独特な匂いがした。","河边有种雨后特有的气味。"]],"v-0bce17c2-2ed7-11ef-a183-99ad05e145f0":[["大きな皿に盛ると、質素な料理も豪華に見えた。","盛在大盘里，朴素的菜也显得丰盛。"],["古い劇場には豪華な照明が残っていた。","旧剧场里还留着华丽的灯具。"]],"v-0cf489ec-2ed7-11ef-a183-99ad05e145f0":[["道を知っている友人が一緒で頼もしかった。","熟悉道路的朋友同行，让人很放心。"],["初めての現場でも落ち着いていて頼もしい。","第一次到现场也很镇定，真靠得住。"]],"v-0b721abc-2ed7-11ef-a183-99ad05e145f0":[["弟はわがままを言って先に席を取ろうとした。","弟弟任性地闹着要先占座。"],["わがままを聞いてもらってばかりではいけない。","不能总让别人顺着自己的任性。"]],"v-0b9efdd4-2ed7-11ef-a183-99ad05e145f0":[["一人旅なら予定を自由に変えられて気楽だ。","独自旅行可以随意改计划，很自在。"],["気楽な気持ちで、まず見本を一つ作った。","我抱着轻松的心态先做了一个样品。"]],"v-0b987978-2ed7-11ef-a183-99ad05e145f0":[["偉大な発見の裏には地道な観察があった。","伟大发现背后有踏实的观察。"],["彼女の偉大な功績を、地元の資料館が紹介している。","当地资料馆在介绍她的伟大功绩。"]],"v-0b925cfa-2ed7-11ef-a183-99ad05e145f0":[["たまには少し贅沢をして、窓の広い部屋に泊まった。","偶尔奢侈一下，我住进了有大窗的房间。"],["時間に追われず本を読むのは、私には贅沢だ。","能不赶时间地读书，对我来说很奢侈。"]],"v-79b19692-679e-11ef-89c9-3b0955f1365d":[["分厚い板はこの道具では切れない。","厚板用这件工具切不开。"],["冬の山には分厚い上着を持っていった。","冬天上山，我带了件厚外套。"]],"v-79b1cf72-679e-11ef-89c9-3b0955f1365d":[["この二つの故障は無関係だった。","这两起故障没有关系。"],["本題と無関係な話は別の機会にしよう。","与正题无关的话改天再谈吧。"]],"v-0bb05714-2ed7-11ef-a183-99ad05e145f0":[["急いで買い替えると損をするかもしれない。","着急换新可能会吃亏。"],["送料を計算せずに売ったので、少し損が出た。","因为卖出前没算邮费，亏了一点。"]],"v-0c05e0a8-2ed7-11ef-a183-99ad05e145f0":[["風が止むと、水面に窓が映った。","风停后，水面映出了窗户。"],["投げた石が水面を二度跳ねた。","扔出去的石子在水面上跳了两下。"]],"v-0cd85c68-2ed7-11ef-a183-99ad05e145f0":[["細い線で繊細な模様を描いた。","我用细线画了精致的花样。"],["彼女は声に出さない気持ちにも気づく、繊細な人だ。","她心思细腻，能察觉别人没说出口的心情。"]],"v-0bddb876-2ed7-11ef-a183-99ad05e145f0":[["椅子が不安定なので脚を調べた。","椅子不稳，我检查了椅腿。"],["天候が不安定で、出発時刻を決められなかった。","天气不稳定，无法确定出发时间。"]],"v-0c10dada-2ed7-11ef-a183-99ad05e145f0":[["夜は人通りが少なく、少し物騒だ。","夜里行人少，有点不安全。"],["誰かが鍵を壊したと聞くと、物騒な話だと思った。","听说有人弄坏了锁，我觉得这事挺吓人。"]],"v-79b2c58a-679e-11ef-89c9-3b0955f1365d":[["映画の街並みは驚くほどリアルだった。","电影里的街景真实得惊人。"],["現地で聞いた話が、作品の描写をリアルにした。","在当地听到的故事让作品的描写更真实。"]],"v-0c45134a-2ed7-11ef-a183-99ad05e145f0":[["これ以上の説明は無用だと判断した。","我判断无需再作说明。"],["予約した人には、順番の心配は無用だ。","已经预约的人无需担心排队。"]],"v-0bafa6b6-2ed7-11ef-a183-99ad05e145f0":[["雨上がりの空気は爽やかだった。","雨后的空气很清爽。"],["冷たい水を飲むと、気分が爽やかになった。","喝了凉水，感觉神清气爽。"]],"v-0b88f48a-2ed7-11ef-a183-99ad05e145f0":[["店が遠く、車がないと少し不自由だ。","商店很远，没有车有点不方便。"],["片手が不自由な祖父も使いやすい道具を作った。","我们做了连一只手活动不便的爷爷也容易用的工具。"]],"v-0c0bdb3e-2ed7-11ef-a183-99ad05e145f0":[["彼女は質問に的確に答えた。","她准确地回答了问题。"],["図を一枚加えたのは的確な判断だった。","补上一幅图是个恰当的判断。"]],"v-0c34ef56-2ed7-11ef-a183-99ad05e145f0":[["経験者がいてくれると心強い。","有经验的人在，心里就踏实。"],["遠い町でも、知り合いが迎えに来ると思うと心強かった。","虽然是远方的小镇，想到有熟人来接就安心了。"]],"v-0c1c9730-2ed7-11ef-a183-99ad05e145f0":[["家族でささやかなお祝いをした。","全家简单庆祝了一下。"],["帰り際にささやかな贈り物を渡した。","分别时，我送了一份小礼物。"]],"v-0c5da810-2ed7-11ef-a183-99ad05e145f0":[["この机は頑丈で、重い機械を置いても揺れない。","这张桌子很结实，放上重机器也不晃。"],["風に飛ばされないよう、頑丈な箱に入れた。","为免被风吹走，我放进了结实的盒子。"]],"v-0bfbabec-2ed7-11ef-a183-99ad05e145f0":[["地図で見るより険しい坂だった。","这个坡比地图上看起来更陡。"],["質問を聞いたとたん、彼の顔つきが険しくなった。","一听到问题，他的神情就严厉起来。"]],"v-0bad774c-2ed7-11ef-a183-99ad05e145f0":[["小さな変更でも、性能に影響が出ないか先に確かめた。","即使是小变动，我们也先确认会不会影响性能。"],["実際に使った人から、性能について意見を聞いた。","我们向实际使用者征求了对性能的意见。"]],"v-0bfbdf2c-2ed7-11ef-a183-99ad05e145f0":[["入口は夜になると厳重に施錠される。","到了晚上，入口会严密上锁。"],["管理者から、道具を戻すよう厳重な注意を受けた。","管理员郑重警告，要把工具放回原处。"]],"v-0bd61922-2ed7-11ef-a183-99ad05e145f0":[["小さな変更でも、組み合わせに影響が出ないか先に確かめた。","即使是小变动，我们也先确认会不会影响搭配。"],["実際に使った人から、組み合わせについて意見を聞いた。","我们向实际使用者征求了对搭配的意见。"]],"v-0c122868-2ed7-11ef-a183-99ad05e145f0":[["この図書室には町の歴史に関する資料が豊富にある。","这间图书室有丰富的小镇历史资料。"],["山の水が豊富な地域では、水路がよく発達した。","山水丰富的地区，水渠发展得很好。"]],"v-0c41ff7a-2ed7-11ef-a183-99ad05e145f0":[["接触不良で照明がついたり消えたりした。","接触不良导致灯忽明忽灭。"],["印刷不良の札を取り除いた。","我们挑出了印刷有问题的牌子。"]],"v-0bfb0e58-2ed7-11ef-a183-99ad05e145f0":[["皆で劇の面白さについて話した。","大家聊了戏剧有意思的地方。"],["劇に関する展示を見て、今まで知らなかったことを一つ覚えた。","看了有关戏剧的展览，我记住了一件从前不知道的事。"]],"v-0b8da8b8-2ed7-11ef-a183-99ad05e145f0":[["あいにく窓口が閉まっていて、券を買えなかった。","不巧窗口关着，没买到票。"],["あいにくその日は留守にしております。","不巧那天我不在。"]],"v-0c252116-2ed7-11ef-a183-99ad05e145f0":[["この道では街灯が皆無だった。","这条路上一盏路灯也没有。"],["工事の写真は皆無で、残ったのは図面だけだった。","施工照片一张都没有，只剩图纸。"]],"v-0c596fca-2ed7-11ef-a183-99ad05e145f0":[["臆病な猫は、知らない人が来ると隠れる。","胆小的猫看见生人来就会躲起来。"],["失敗が続き、新しいことを試すのに臆病になった。","连续失败后，我不太敢尝试新事物了。"]],"v-0c3bacc4-2ed7-11ef-a183-99ad05e145f0":[["工事の期間を大幅に短縮できた。","施工时间大幅缩短了。"],["夏には利用者が大幅に増えた。","到了夏天，使用者大幅增加。"]],"v-0ca6eed0-2ed7-11ef-a183-99ad05e145f0":[["犬は玄関に近づいた猫を威嚇した。","狗威吓了靠近门厅的猫。"],["鳥は羽を広げて敵を威嚇する。","鸟展开翅膀威吓敌人。"]],"v-0c9afb5c-2ed7-11ef-a183-99ad05e145f0":[["暗い道で足音がしてぞっとした。","暗路上传来脚步声，我吓得一哆嗦。"],["事故が起きていたかと思うとぞっとする。","一想到差点出事故，我就不寒而栗。"]],"v-0bb4a256-2ed7-11ef-a183-99ad05e145f0":[["定期券を買う方が得だと分かった。","我发现买月票更划算。"],["余った材料を使い切れば、少し得になる。","用完剩余材料，会省一点钱。"]],"v-0cf4814a-2ed7-11ef-a183-99ad05e145f0":[["未知の町を歩きたいという欲求が強くなった。","我越来越想在陌生小镇走走。"],["何でも集めたい欲求を少し抑えた。","我稍稍克制了什么都想收集的欲望。"]],"v-0bad56a4-2ed7-11ef-a183-99ad05e145f0":[["夜の睡眠が足りず、朝の作業に集中できなかった。","夜里睡眠不足，早上干活没法集中注意力。"],["昼に長く寝ると、夜の睡眠に影響する。","白天睡太久会影响夜里的睡眠。"]],"v-6cd621c0-b061-11ef-b775-e7560ea47657":[["皆の前で褒められ、気恥ずかしくなった。","被当众夸奖，我有点不好意思。"],["昔の作文を読むと、今でも少し気恥ずかしい。","读起以前的作文，现在还是有点害臊。"]],"v-79b99f22-679e-11ef-89c9-3b0955f1365d":[["白い布に鮮明な青で線を引いた。","我在白布上画了一道鲜艳的蓝线。"],["旅の最後に見た空が、今も鮮明に思い出せる。","旅程最后看到的天空，至今还能清楚想起。"]],"v-79b9a76a-679e-11ef-89c9-3b0955f1365d":[["この土は豆を育てるのに最適だ。","这种土最适合种豆子。"],["風を避けられる場所が休憩に最適だった。","能避风的地方最适合休息。"]],"v-0c269cd0-2ed7-11ef-a183-99ad05e145f0":[["頑固な父は、何を言っても予定を変えなかった。","倔强的爸爸无论别人怎么说都没改计划。"],["頑固な汚れを柔らかいブラシでこすった。","我用软刷刷洗顽固污渍。"]],"v-0cf44068-2ed7-11ef-a183-99ad05e145f0":[["申請には本人の署名を要する。","申请需要本人签名。"],["橋の修理はおよそ半年を要した。","修桥花了约半年。"]],"v-0c159aac-2ed7-11ef-a183-99ad05e145f0":[["凍った道では足元に用心した。","在结冰的路上，我小心脚下。"],["念のため、戸締まりには十分用心した。","为保险起见，我格外留心锁好门窗。"]],"v-0c9c5600-2ed7-11ef-a183-99ad05e145f0":[["窓の外で雪がちらちら降っている。","窗外飘着零星雪花。"],["妹は時計をちらちら見ていた。","妹妹时不时瞟一眼钟。"]],"v-0cf122de-2ed7-11ef-a183-99ad05e145f0":[["海とは無縁だった祖父が、初めて船に乗った。","一直和大海无缘的爷爷第一次坐上了船。"],["機械とは無縁の仕事だと思っていた。","我本以为这项工作与机械无关。"]],"v-0c0c1ce8-2ed7-11ef-a183-99ad05e145f0":[["徹夜して地図を描き直した。","我通宵重画了地图。"],["徹夜明けは、数字を読み違えやすかった。","熬了一夜后，容易看错数字。"]],"v-0ba8083e-2ed7-11ef-a183-99ad05e145f0":[["数年分を並べて、実績がどう変わったか比べた。","我把好几年的数据排在一起，比较实际业绩如何变化。"],["会議で実績を確認し、次の予定を決めた。","会上确认了实际业绩，随后定下下一项安排。"]],"v-0bcd9450-2ed7-11ef-a183-99ad05e145f0":[["開店前の店内は慌ただしかった。","开门前，店里忙忙碌碌。"],["朝は慌ただしくて手紙を読む暇もなかった。","早上太匆忙，连读信的工夫都没有。"]],"v-0c231d9e-2ed7-11ef-a183-99ad05e145f0":[["午後になると、一転して雨になった。","一到下午，天气突变，下起了雨。"],["笑顔だった父の表情が一転した。","原本笑着的爸爸，神情一下子变了。"]],"v-0bf679f6-2ed7-11ef-a183-99ad05e145f0":[["日が入る部屋は冬でも快適だった。","能晒到阳光的房间，即使冬天也很舒适。"],["快適に歩けるよう、荷物を減らした。","为了走得舒服，我精简了行李。"]],"v-0c2b577a-2ed7-11ef-a183-99ad05e145f0":[["子どもの好奇心には限りないものがある。","孩子的好奇心是无穷的。"],["山の向こうには限りない海が広がっているように見えた。","山的另一边仿佛展开了无边的大海。"]],"v-0c7749f0-2ed7-11ef-a183-99ad05e145f0":[["現地の人から尊い教えを受けた。","我从当地人那里得到了宝贵的教导。"],["小さな生き物の命も尊い。","小小生物的生命也同样珍贵。"]],"v-0bd4c7b6-2ed7-11ef-a183-99ad05e145f0":[["兄は成人してからも実家に住んでいた。","哥哥成年后仍住在父母家。"],["この行事は成人を迎えた人を祝う。","这项活动是为庆祝步入成年的人举办的。"]],"v-0bb6a182-2ed7-11ef-a183-99ad05e145f0":[["弟は一方的に決められた規則に反抗した。","弟弟反抗单方面制定的规则。"],["物語の主人公は村の古いしきたりに反抗する。","故事主人公反抗村里的旧习俗。"]],"v-0c08c7d2-2ed7-11ef-a183-99ad05e145f0":[["この人数なら、部屋を二つ借りるのが妥当だ。","按这个人数，借两间房比较合理。"],["集めた資料で、結論が妥当か確かめた。","我们用收集到的材料检验结论是否合理。"]],"v-0c83bda2-2ed7-11ef-a183-99ad05e145f0":[["同じ原因なら、同じ結果になるのは必然だ。","如果原因相同，结果相同也是必然的。"],["偶然に見えたが、資料を読むと必然の結果だった。","看似偶然，读了材料才知道是必然的结果。"]],"v-0be424a4-2ed7-11ef-a183-99ad05e145f0":[["この海岸で雪が積もるのはまれだ。","这片海岸很少积雪。"],["古い建物がこの状態で残る例はまれだ。","老建筑以这种状态保存下来的例子不多。"]],"v-0c16e6f0-2ed7-11ef-a183-99ad05e145f0":[["長時間の労働で手が疲れた。","长时间干活，手累了。"],["労働の条件について店の人と話した。","我和店里的人谈了劳动条件。"]],"v-0b9d098e-2ed7-11ef-a183-99ad05e145f0":[["大学で初めて、学問として歴史を学んだ。","我到了大学才第一次把历史作为学问系统地学习。"],["彼は年を重ねても学問を続けた。","他年纪渐长，仍继续做学问。"]],"v-0c75348a-2ed7-11ef-a183-99ad05e145f0":[["二台のうち、小さい車が先行した。","两辆车中，小车先走。"],["正式な販売に先行して、試作品を公開した。","正式发售前先公开了样品。"]],"v-0c7ef63c-2ed7-11ef-a183-99ad05e145f0":[["使い心地は、値段の高い品と同等だった。","用起来和更贵的产品相当。"],["三つの班には同等の時間を与えた。","给三个小组分配了同样长的时间。"]],"v-0c6e3b3a-2ed7-11ef-a183-99ad05e145f0":[["まだ熟していない柿は渋い。","还没熟的柿子发涩。"],["祖父は渋い色の上着を好んだ。","爷爷喜欢颜色素雅的外套。"]],"v-0bf30352-2ed7-11ef-a183-99ad05e145f0":[["椅子に座り、肩の力を抜いてリラックスした。","我坐到椅子上，放松肩膀。"],["発表前にリラックスできる曲を聞いた。","发言前我听了首让人放松的曲子。"]],"v-0c8c0976-2ed7-11ef-a183-99ad05e145f0":[["古い写真が年代を特定する有力な手掛かりになった。","旧照片成了确定年代的有力线索。"],["この案は費用が少ないため、有力な候補だ。","这个方案费用少，是个有力的备选。"]],"v-4c3c2f52-4b5d-11f1-a630-0ddc817ad47e":[["棚の奥を見るために背伸びをした。","我踮脚往架子深处看。"],["背伸びをして難しい本を買ったが、まだ読めない。","我逞强买了本难书，现在还读不懂。"]],"v-0baf2da8-2ed7-11ef-a183-99ad05e145f0":[["町の選挙で初めて投票した。","我第一次在镇上的选举中投了票。"],["選挙の候補者が公開の場で意見を述べた。","选举候选人在公开场合发表了意见。"]],"v-0c4e8470-2ed7-11ef-a183-99ad05e145f0":[["彼は腕がたくましく、箱を二つ持ち上げた。","他胳膊结实，一下提起两个箱子。"],["厳しい環境でも、たくましく育った苗がある。","即使环境严酷，也有长势强健的幼苗。"]],"v-0ba2485e-2ed7-11ef-a183-99ad05e145f0":[["褒められても、彼女は謙遜して仲間のおかげだと言った。","即使被夸，她也谦虚地说是伙伴的功劳。"],["謙遜せず、今回は自分の成果をそのまま話した。","这次我没有谦让，如实说了自己的成果。"]],"v-0bcbd4bc-2ed7-11ef-a183-99ad05e145f0":[["姉は駅の近くの病院に勤務している。","姐姐在车站附近的医院上班。"],["夜間の勤務が終わってから家に帰った。","夜班结束后，我回了家。"]],"v-0bfa87e4-2ed7-11ef-a183-99ad05e145f0":[["子どものころ、雲の上の町を空想した。","小时候，我想象过云上的小镇。"],["地図の白い部分に何があるか空想するのが楽しい。","想象地图空白处有什么，很有趣。"]],"v-49ade4bc-b061-11ef-b775-e7560ea47657":[["最初の試作品は思い通りに動かなかった。","第一个样品没有按预想运转。"],["準備を重ね、ようやく思い通りの色が出た。","反复准备后，终于做出了想要的颜色。"]],"v-0c89ebfa-2ed7-11ef-a183-99ad05e145f0":[["無口な兄が珍しく長い話をした。","寡言的哥哥难得说了很长一段话。"],["彼女は無口だが、困ったときはそっと手を貸す。","她话不多，但有人遇到困难时会默默帮忙。"]],"v-0c5aa9da-2ed7-11ef-a183-99ad05e145f0":[["議論が過激になり、司会者が休憩を入れた。","讨论变得激烈过头，主持人安排了休息。"],["過激な言い方を避け、事実だけ書いた。","我避开激烈措辞，只写了事实。"]],"v-0c8e61f8-2ed7-11ef-a183-99ad05e145f0":[["窓を開けると電波の状態が良好になった。","打开窗后，信号变好了。"],["古い絵だが保存状態は良好だった。","画虽旧，保存状况却很好。"]],"v-79bf9d82-679e-11ef-89c9-3b0955f1365d":[["彼女は会議で賛成の意向を表明した。","她在会上表明了赞成的意向。"],["店は計画を延期する方針を表明した。","店家表示将推迟计划。"]],"v-79bfcd66-679e-11ef-89c9-3b0955f1365d":[["新しい建物は洗練された外観だった。","新楼的外观简洁雅致。"],["何度も推敲し、説明が洗練されていった。","经过反复推敲，讲解逐渐变得精炼。"]],"v-629970a6-4b5e-11f1-a630-0ddc817ad47e":[["就職してから友人と同居した。","工作后我和朋友同住。"],["祖母と同居していたころ、よく昔話を聞いた。","与奶奶同住时，我常听她讲旧事。"]],"v-0bae0d42-2ed7-11ef-a183-99ad05e145f0":[["子どもは絵を描くときが一番生き生きしている。","孩子画画时最有活力。"],["旅先の景色が文章に生き生きと描かれていた。","旅途景色在文章里被描绘得栩栩如生。"]],"v-0bf551a2-2ed7-11ef-a183-99ad05e145f0":[["朝の静かなうちに沖へ向かった。","趁早上安静，我朝近海出发。"],["撮影した写真を見返すと、夕方の沖は朝とは違って見えた。","回看照片时，我发现傍晚的近海看起来与清晨不同。"]],"v-0b4b1c78-2ed7-11ef-a183-99ad05e145f0":[["クリスマスの日には、家族でいつもと違う料理を作った。","圣诞节那天，全家做了和平时不同的菜。"],["町の行事がクリスマスと重なり、日程を少しずらした。","镇里的活动赶上了圣诞节，于是稍稍调整了日期。"]],"v-0cd53d44-2ed7-11ef-a183-99ad05e145f0":[["畳の上で正座して祖母の話を聞いた。","我跪坐在榻榻米上听奶奶说话。"],["長い時間正座していたので足がしびれた。","跪坐太久，腿麻了。"]],"v-0c1b7d50-2ed7-11ef-a183-99ad05e145f0":[["弟は駅の出口を探してきょろきょろしていた。","弟弟东张西望地找车站出口。"],["名前を呼ばれると、子どもは辺りをきょろきょろ見回した。","听见有人叫名字，孩子东张西望。"]],"v-d833986a-4b62-11f1-a630-0ddc817ad47e":[["窓を開けると白い布がひらめいた。","打开窗后，白布迎风飘动。"],["階段を下りる途中で解決策がひらめいた。","下楼时，我突然想到了办法。"]],"v-0b780cf6-2ed7-11ef-a183-99ad05e145f0":[["山を歩くとすぐおなかがすく。","一爬山肚子很快就饿。"],["店がすく時間に昼食を取りに行った。","我趁店里人少去吃午饭。"]],"v-0c8b74ca-2ed7-11ef-a183-99ad05e145f0":[["この島には野生の鹿がいる。","这个岛上有野鹿。"],["庭の外で野生の花が咲いた。","院外开了野花。"]],"v-0c079240-2ed7-11ef-a183-99ad05e145f0":[["岸に沿って川を遡ると、水車があった。","沿着岸逆流而上，能见到一座水车。"],["記録を明治時代まで遡って調べた。","我把记录追溯到明治时代来调查。"]],"v-0c1d0a1c-2ed7-11ef-a183-99ad05e145f0":[["雨上がりの土はしっとりしていた。","雨后的泥土湿润。"],["夕方の庭にはしっとりとした趣があった。","傍晚的庭院有一种静雅的韵味。"]],"v-0bd79748-2ed7-11ef-a183-99ad05e145f0":[["猫が見つかり、子どもは大喜びした。","找到猫了，孩子高兴极了。"],["祖母は新しい写真を見て大喜びだった。","奶奶看到新照片，高兴得不得了。"]],"v-0ca407b0-2ed7-11ef-a183-99ad05e145f0":[["説明を読んでも、気持ちはもやもやしたままだ。","读完说明，心里还是闷闷的。"],["湯気がもやもやと窓のそばに漂っていた。","一团团水汽飘在窗边。"]],"v-79cb0d02-679e-11ef-89c9-3b0955f1365d":[["片付けが一段落したところで、水を飲んだ。","收拾工作告一段落，我喝了点水。"],["仕事が一段落したら、古い友人に会いに行く。","工作告一段落后，我会去见老友。"]],"v-b9e6b760-692e-11ef-95f0-b30e867324a9":[["台風は町の南へそれた。","台风偏到了小镇南边。"],["話が本題からそれたので、資料に戻った。","话题偏离正题，我就重新回到材料上。"]],"v-0becb678-2ed7-11ef-a183-99ad05e145f0":[["駅で柱にもたれて友人を待った。","我在车站靠着柱子等朋友。"],["夜遅くに揚げ物を食べると胃がもたれる。","深夜吃油炸食品会觉得胃胀。"]],"v-79cd0396-679e-11ef-89c9-3b0955f1365d":[["自転車の車輪に長い草が絡まった。","长草缠到了自行车轮上。"],["二本の糸が絡まって、別々に巻けない。","两根线缠在一起，不能分开卷了。"]],"v-3b981466-636c-11ef-91a6-d1e41ee21c0f":[["係員が観客の興奮を鎮めた。","工作人员让兴奋的观众平静下来。"],["子どもの不安を鎮めようと、母は手を握った。","妈妈握住孩子的手，试着安抚他的不安。"]],"v-79cdeb6c-679e-11ef-89c9-3b0955f1365d":[["雨が弱まり、試合を続行した。","雨势减弱，比赛继续。"],["途中で方法を変えたが、調査は続行した。","中途改了方法，但调查继续进行。"]],"v-0cb08ec2-2ed7-11ef-a183-99ad05e145f0":[["調べ始める前に、感性の意味を資料で確かめた。","开始调查前，我查阅材料确认了感性的含义。"],["説明では、感性について具体的な事例を挙げた。","讲解时，我们举了有关感性的具体例子。"]],"v-0c5b53d0-2ed7-11ef-a183-99ad05e145f0":[["現物を前にすると、写真では分からなかった外観に気づいた。","看到实物后，我察觉到了照片里看不出的外观。"],["二つの試作品を並べ、外観の違いを確かめた。","我们把两个样品并排放置，核对了外观的差异。"]],"v-0c538452-2ed7-11ef-a183-99ad05e145f0":[["船に乗ってから胃がむかつく。","上船以后我就觉得胃里恶心。"],["約束を破ったのに謝らない彼にむかついた。","他违约却不道歉，真让我生气。"]],"v-0c14e1b6-2ed7-11ef-a183-99ad05e145f0":[["その日のうちに返事が来るとは予期していなかった。","我没料到当天就会有答复。"],["予期せぬ風で看板が倒れた。","突如其来的风吹倒了招牌。"]],"v-0c205b4a-2ed7-11ef-a183-99ad05e145f0":[["焼き上がったパンは中がふんわりしていた。","刚烤好的面包里面松软。"],["白い羽がふんわりと地面に落ちた。","白羽毛轻飘飘地落在地上。"]],"v-0c94a7ca-2ed7-11ef-a183-99ad05e145f0":[["値段を決めるまで店主との駆け引きが続いた。","和店主讨价还价了好一会儿才定价。"],["勝負の終盤では、駆け引きがものを言った。","胜负将分时，战术较量起了决定作用。"]],"v-0bec4f9e-2ed7-11ef-a183-99ad05e145f0":[["かばんの中身が片側に偏った。","包里的东西都偏到一边了。"],["質問が一つの分野に偏らないようにした。","我尽量避免问题集中在同一个领域。"]],"v-0b9faeaa-2ed7-11ef-a183-99ad05e145f0":[["帰りのバスでつい居眠りした。","我不小心在回程公交上打了个盹。"],["暖かい部屋で祖父が居眠りしていた。","爷爷在暖和的房间里打瞌睡。"]],"v-0cf9f756-2ed7-11ef-a183-99ad05e145f0":[["雪が降り始めると、通りはしんとした。","下雪后，街道静悄悄的。"],["発表が終わった瞬間、会場はしんと静まり返った。","发言结束的那一刻，会场鸦雀无声。"]],"v-0c6d54c2-2ed7-11ef-a183-99ad05e145f0":[["転んでぶつけた膝が腫れてきた。","摔倒撞到的膝盖肿了起来。"],["朝起きたら、右のまぶたが腫れていた。","早上起来一看，右眼皮肿了。"]],"v-0b919d4c-2ed7-11ef-a183-99ad05e145f0":[["皆でショーの面白さについて話した。","大家聊了演出有意思的地方。"],["ショーに関する展示を見て、今まで知らなかったことを一つ覚えた。","看了有关演出的展览，我记住了一件从前不知道的事。"]],"v-0c035ec8-2ed7-11ef-a183-99ad05e145f0":[["窓口では午後もご相談を承ります。","下午窗口也受理咨询。"],["ご希望の日時を承ってから部屋を手配します。","我们了解您期望的时间后会安排房间。"]],"v-0c38f344-2ed7-11ef-a183-99ad05e145f0":[["雨水が木の板の内側まで染みた。","雨水渗到了木板里面。"],["冷たい水が治療中の歯に染みる。","冷水刺激正在治疗的牙齿，疼得很。"]],"v-0b76632e-2ed7-11ef-a183-99ad05e145f0":[["気候の変化を調べるため、過去十年の記録を表にした。","为了考察气候的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、気候にどのような傾向があるか説明した。","我们用调查结果解释了气候有什么趋势。"]],"v-0ba27c66-2ed7-11ef-a183-99ad05e145f0":[["波の向こうに島が姿を現した。","海浪远处显出了一座岛。"],["彼は顔に不満を現した。","他的脸上显出了不满。"]],"v-0bbe457c-2ed7-11ef-a183-99ad05e145f0":[["窓口で古い券を新しい券に換えた。","我在窗口把旧券换成了新券。"],["旅の前に円を現地の通貨に換えておいた。","旅行前我先把日元换成了当地货币。"]],"v-79dbff86-679e-11ef-89c9-3b0955f1365d":[["祖母は祭りの朝に私の髪を結ってくれた。","庆典当天早上，奶奶给我扎了头发。"],["鏡を見ながら一人で髪を結う練習をした。","我照着镜子练习自己扎头发。"]],"v-0c3e9c22-2ed7-11ef-a183-99ad05e145f0":[["現地で道端の状態を調べ、気づいたことを地図に書き込んだ。","我在现场调查路旁，并把注意到的事情标在地图上。"],["季節が変わってから、道端の様子をもう一度見に行った。","换季以后，我又去看了一次路旁的情况。"]],"v-0bece08a-2ed7-11ef-a183-99ad05e145f0":[["同じ姿勢で座り続けて足がしびれた。","一直保持同一坐姿，腿麻了。"],["彼の力強い演奏にしびれた。","他有感染力的演奏让我陶醉。"]],"v-0bf04360-2ed7-11ef-a183-99ad05e145f0":[["職人はテクニックを使って、見本と同じ形を作った。","工匠用技巧做出了和样品一样的形状。"],["説明を聞いたあと、テクニックの扱いを練習した。","听完讲解后，我练习了如何运用技巧。"]],"v-0b9a135a-2ed7-11ef-a183-99ad05e145f0":[["工事のあと、水の汚染が見つかった。","施工后发现水体受到了污染。"],["井戸が汚染されないよう、周囲の排水を調べた。","为防止井水被污染，我们检查了周边排水。"]],"v-b010485c-4c65-11f1-9103-c10b58500570":[["あの一言が、彼女を旅へと突き動かした。","那句话促使她踏上了旅程。"],["自分の目で確かめたいという思いが私を突き動かした。","想亲眼确认的念头推动我行动。"]],"v-0bd7c060-2ed7-11ef-a183-99ad05e145f0":[["昔の資料には大戦の様子が細かく書かれていた。","旧资料细致地写了大战的情况。"],["大戦のことを祖父から聞き、覚えている話を記録した。","我听爷爷讲了大战，把记得的内容写下来。"]],"v-79e32d74-679e-11ef-89c9-3b0955f1365d":[["板の裏に小さな突起が二つあった。","板背面有两个小突起。"],["箱がずれないように、底に突起を付けた。","为避免盒子移位，我们在底部加了突起。"]],"v-0ba00210-2ed7-11ef-a183-99ad05e145f0":[["紙の端が引き出しに挟まった。","纸边夹在抽屉里了。"],["意見の違う二人の間に挟まって困った。","夹在意见不同的两人之间，我很为难。"]],"v-0c332c16-2ed7-11ef-a183-99ad05e145f0":[["雨が続いて木の窓枠が傷んだ。","一直下雨，木窗框受损了。"],["果物は傷む前に食べてしまおう。","水果趁坏掉之前吃完吧。"]],"v-fcb23e02-4c67-11f1-9103-c10b58500570":[["今お電話しても差し支えないでしょうか。","现在打电话给您方便吗？"],["明日の仕事に差し支えるので、今夜は早く寝る。","为了不影响明天工作，今晚早点睡。"]],"v-0c0184a4-2ed7-11ef-a183-99ad05e145f0":[["新学期から三年生の授業を受け持つ。","新学期起，我负责三年级的课。"],["展示会で案内を受け持つことになった。","我被安排负责展会引导。"]],"v-0bfe2f16-2ed7-11ef-a183-99ad05e145f0":[["転びそうな人に手を差し伸べた。","我向快跌倒的人伸手相助。"],["困っている店に、近所の人が援助の手を差し伸べた。","附近居民向遇到困难的店家伸出了援手。"]],"v-0bf39ae2-2ed7-11ef-a183-99ad05e145f0":[["人の前で威張っても、誰もついてこない。","在人前摆架子，也不会有人愿意跟随。"],["兄は年下の子に威張らず、話をよく聞いた。","哥哥没有对年纪小的孩子摆架子，还认真听他们说话。"]],"v-49b9c7d2-b061-11ef-b775-e7560ea47657":[["雪の日には、近所同士で助け合った。","下雪时，邻里互相帮忙。"],["分からない箇所があれば、班の仲間と助け合う。","有不懂的地方，就和同组伙伴互相帮助。"]],"v-0c6adaee-2ed7-11ef-a183-99ad05e145f0":[["家で鳥を飼育するため、専用のかごを作った。","为在家里养鸟，我做了个专用笼子。"],["飼育員は動物の飼育の記録を毎日つけている。","饲养员每天都写动物饲养记录。"]],"v-0c1673fa-2ed7-11ef-a183-99ad05e145f0":[["この説明では詳しい経緯を略した。","这段说明省略了详细经过。"],["長い施設名を略して呼ぶ人が多い。","很多人用简称称呼这家名字很长的机构。"]],"v-0c4b69d4-2ed7-11ef-a183-99ad05e145f0":[["遠くから来たゲストのために、駅まで迎えに行った。","我到车站迎接远道而来的嘉宾。"],["ゲストと話して、以前知らなかった話を聞けた。","与嘉宾交谈后，我听说了以前不知道的事。"]],"v-0c3d013c-2ed7-11ef-a183-99ad05e145f0":[["朝の静かなうちに頂へ向かった。","趁早上安静，我朝山顶出发。"],["撮影した写真を見返すと、夕方の頂は朝とは違って見えた。","回看照片时，我发现傍晚的山顶看起来与清晨不同。"]],"v-0c6b28dc-2ed7-11ef-a183-99ad05e145f0":[["夕方まで強い風が持続した。","大风持续到傍晚。"],["短い休憩を挟むと、集中が持続しやすい。","中间短暂休息，有助于持续集中注意力。"]],"v-0bd3d5ea-2ed7-11ef-a183-99ad05e145f0":[["子どものころから短歌に親しんできた。","我从小就经常接触短歌。"],["水辺の生き物に親しむ機会を作った。","我们创造了亲近水边生物的机会。"]],"v-0c98a0e6-2ed7-11ef-a183-99ad05e145f0":[["犬は水が苦手で、抱き上げるとじたばたした。","狗怕水，一被抱起来就乱扑腾。"],["今さらじたばたしても仕方がない。","事到如今，再怎么着急也没用了。"]],"v-0c58784a-2ed7-11ef-a183-99ad05e145f0":[["古い資料は指定の部屋で閲覧できる。","旧材料可以在指定房间查阅。"],["閲覧を希望する人は、先に予約してください。","希望阅览的人请先预约。"]],"v-49bc31a2-b061-11ef-b775-e7560ea47657":[["会場にはピアスが置かれ、実際に手に取ることができた。","会场摆着耳环，人们可以亲手拿起来看。"],["持ち帰ったピアスを家族に見せ、どこで見つけたか説明した。","我把带回来的耳环给家人看，讲了是在哪儿发现的。"]],"v-73b7cb9c-4ce1-11f1-90a9-0fc8163987fc":[["投げる直前に力んで、球がそれた。","出手前太用力，球偏了。"],["力まずに筆を持つと線が滑らかになった。","放松握笔，线条就流畅了。"]],"v-0baf0cce-2ed7-11ef-a183-99ad05e145f0":[["削ったばかりの鉛筆は先が尖っている。","刚削好的铅笔尖端很尖。"],["疲れてくると、彼の声は少し尖る。","一累起来，他的语气就有些尖锐。"]],"v-0c0df4d2-2ed7-11ef-a183-99ad05e145f0":[["鍋をゆっくり熱してから、油を入れた。","我慢慢把锅烧热，再倒油。"],["試料を熱すると、色が少し変わった。","给样品加热后，颜色稍有变化。"]],"v-0bfd3e1c-2ed7-11ef-a183-99ad05e145f0":[["春になり、祖父は畑を耕した。","春天到了，爷爷耕了地。"],["作物を植える前に土を深く耕す。","种作物前先深翻土地。"]],"v-0bfc2978-2ed7-11ef-a183-99ad05e145f0":[["古典に興味を持ち、入門書を一冊選んだ。","我对古典文学产生了兴趣，选了一本入门书。"],["公開講座で古典について学び、以前とは違う見方をするようになった。","在公开课上学了古典文学后，我开始有不同的看法。"]],"v-0c2529e0-2ed7-11ef-a183-99ad05e145f0":[["庭の梅が去年より早く開花した。","院里的梅花比去年开得早。"],["長い練習の末に、彼女の才能が開花した。","长期练习后，她的才能得以绽放。"]],"v-0bd69776-2ed7-11ef-a183-99ad05e145f0":[["雪が強くなり、駅へ向かう足を速めた。","雪下大了，我加快脚步往车站走。"],["水を温めると反応を速められる。","把水加热可以加快反应。"]],"v-0c26d844-2ed7-11ef-a183-99ad05e145f0":[["正月に列車で帰省した。","新年时我坐电车回乡探亲。"],["帰省の前に、祖母に到着時刻を知らせた。","回乡前，我把到达时间告诉了奶奶。"]],"v-0b8e5c2c-2ed7-11ef-a183-99ad05e145f0":[["返事がなかなか来ず、いらいらした。","迟迟没有答复，我有些焦躁。"],["弟は渋滞でいらいらしていた。","弟弟因为堵车而心烦。"]],"v-0bf91990-2ed7-11ef-a183-99ad05e145f0":[["忙しかったので、週末は家で休養した。","前阵子太忙，周末我在家休养。"],["休養を取ってから、また作業に戻った。","我休息好后，又回来干活了。"]],"v-79f8e204-679e-11ef-89c9-3b0955f1365d":[["以前の失敗を、次の計画に役立てた。","我把以往的失败经验用在下一项计划中。"],["集めた意見は、案内の見直しに役立てます。","征集到的意见将用于修订指引。"]],"v-0bc9bc4a-2ed7-11ef-a183-99ad05e145f0":[["学力の変化を調べるため、過去十年の記録を表にした。","为了考察学业能力的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、学力にどのような傾向があるか説明した。","我们用调查结果解释了学业能力有什么趋势。"]],"v-0c8d6d3e-2ed7-11ef-a183-99ad05e145f0":[["履歴の記録は、日付が分かるように整理した。","我们把历史记录的记录按能辨明日期的方式整理了。"],["後から履歴を確認するため、関係する資料を残した。","为了以后能核实历史记录，我们留下了相关材料。"]],"v-0be84322-2ed7-11ef-a183-99ad05e145f0":[["低い棚なら荷物の出し入れが楽だ。","架子低，拿取或放入物品都省力。"],["財布から同じカードを何度も出し入れした。","我把同一张卡反复从钱包里拿出又放回。"]],"v-0cc52ea4-2ed7-11ef-a183-99ad05e145f0":[["数年分を並べて、仕入れがどう変わったか比べた。","我把好几年的数据排在一起，比较采购情况如何变化。"],["会議で仕入れを確認し、次の予定を決めた。","会上确认了采购情况，随后定下下一项安排。"]],"v-0b7172b0-2ed7-11ef-a183-99ad05e145f0":[["もたもたしているうちに、バスが出てしまった。","正磨蹭时，公交开走了。"],["手順が分からず、入口でもたもたした。","不懂流程，我在入口耽搁了一会儿。"]],"v-0c1d4ce8-2ed7-11ef-a183-99ad05e145f0":[["底に沈んだ豆を網で掬った。","我用网捞起了沉底的豆子。"],["祖母は両手で井戸の水を掬った。","奶奶用双手掬起井水。"]],"v-0bcd521a-2ed7-11ef-a183-99ad05e145f0":[["口座についての問い合わせを、担当窓口で受け付けた。","办事窗口受理了有关账户的咨询。"],["口座の手続きがどのように変わったか、案内を読んだ。","我读了指引，了解账户的手续有何变化。"]],"v-79fc1f3c-679e-11ef-89c9-3b0955f1365d":[["各班から代表を一人ずつ選出した。","各组选出一名代表。"],["投票で新しい会長を選出する。","通过投票选出新会长。"]],"v-79ae9628-4ce3-11f1-90a9-0fc8163987fc":[["港には、汽笛と人の声が入り交じっていた。","港口里汽笛声和人声交织。"],["期待と不安が入り交じったまま朝を迎えた。","我带着交织的期待和不安迎来了清晨。"]],"v-0bcae6b0-2ed7-11ef-a183-99ad05e145f0":[["朝六時に起床し、列車の時刻を調べた。","我早晨六点起床，查了电车时间。"],["旅行中も起床の時刻を変えなかった。","旅行期间我也没改起床时间。"]],"v-0bf2e1c4-2ed7-11ef-a183-99ad05e145f0":[["朝はランニングのため、玄関をいつもより早く出た。","早上为了跑步，我比往常更早出门。"],["出発前に、ランニングに必要な物を一つずつ確認した。","出发前，我逐一核对了跑步需要的东西。"]],"v-0bcf174e-2ed7-11ef-a183-99ad05e145f0":[["現物を前にすると、写真では分からなかった材質に気づいた。","看到实物后，我察觉到了照片里看不出的材质。"],["二つの試作品を並べ、材質の違いを確かめた。","我们把两个样品并排放置，核对了材质的差异。"]],"v-0c81dd20-2ed7-11ef-a183-99ad05e145f0":[["初日の来場者は去年の同じ日から倍増した。","首日到场人数比去年同一天翻倍。"],["席を倍増させても、全員は座れなかった。","座位即使加倍，也坐不下所有人。"]],"v-0bfafdd2-2ed7-11ef-a183-99ad05e145f0":[["芸能に興味を持ち、入門書を一冊選んだ。","我对表演艺术产生了兴趣，选了一本入门书。"],["公開講座で芸能について学び、以前とは違う見方をするようになった。","在公开课上学了表演艺术后，我开始有不同的看法。"]],"v-7a01e3f4-679e-11ef-89c9-3b0955f1365d":[["この場所から眺める町並みが好きで、何度も足を運んだ。","我喜欢从这里看到的街景，去了好几次。"],["古い写真に写る町並みと、今の景色を比べてみた。","我把老照片里的街景和如今的景色作了比较。"]],"v-82108d6c-4ce8-11f1-90a9-0fc8163987fc":[["最後の試合で地元のチームが圧勝した。","最后一场比赛，本地队取得压倒性胜利。"],["投票では修復案が圧勝し、工事が決まった。","投票中修复方案取得压倒性胜利，施工确定了。"]],"v-0bf15aca-2ed7-11ef-a183-99ad05e145f0":[["ビニールの端を指で押さえ、ずれないようにした。","我用手指按住塑料薄膜的一端，免得移位。"],["長さを確かめてから、ビニールを二つに分けた。","确认长度后，我把塑料薄膜分成两份。"]],"v-0c35eabe-2ed7-11ef-a183-99ad05e145f0":[["歩行者がいる間、車両は進入できない。","有行人时，车辆不得驶入。"],["線路に進入した車両は警報に気づいた。","驶入铁道的车辆注意到了警报。"]],"v-0cea06de-2ed7-11ef-a183-99ad05e145f0":[["各部屋に非常用の懐中電灯を備え付けた。","每个房间都配备了应急手电。"],["記入例は窓口に備え付けてあります。","窗口放有填写示例，可随时查看。"]],"v-c46ff416-4cea-11f1-90a9-0fc8163987fc":[["閉館は六時だと信じ込んでいた。","我认定闭馆时间是六点。"],["弟は地図の青い線が川だと信じ込んだ。","弟弟深信地图上的蓝线是河。"]],"v-0be0a784-2ed7-11ef-a183-99ad05e145f0":[["忘れ物が届いていないか駅に問い合わせた。","我向车站询问有没有人交来失物。"],["参加条件について事務局に問い合わせる。","我会向事务局咨询参加条件。"]],"v-0ce53a64-2ed7-11ef-a183-99ad05e145f0":[["時計に小型の電池が内蔵されている。","钟里内置了小电池。"],["音を出す装置を箱の中に内蔵した。","我们在盒子里内置了发声装置。"]],"v-0cc746bc-2ed7-11ef-a183-99ad05e145f0":[["本物に似せて紙で模型を作った。","我照着实物用纸做了模型。"],["外壁の色を隣の建物に似せた。","我把外墙的颜色做得跟邻楼相似。"]],"v-0bdf4ae2-2ed7-11ef-a183-99ad05e145f0":[["割れやすい器は厚い紙で包装した。","易碎的器皿用厚纸包好。"],["包装を開けると木の匂いがした。","一拆开包装就闻到了木头的气味。"]],"v-7a0ce18c-679e-11ef-89c9-3b0955f1365d":[["山の向こうの班と無線で交信した。","我们用无线电和山另一边的小组通信。"],["雨が強くなり、船との交信が途切れた。","雨下大后，与船只的通信中断了。"]],"v-0c2484cc-2ed7-11ef-a183-99ad05e145f0":[["貨幣を濡らさないよう、箱に入れてから運んだ。","我把货币装进盒子才搬运，免得弄湿。"],["棚から古い貨幣を取り出し、別の場所へ移した。","我从架子上取下旧的货币，移到了别处。"]],"v-0c14f188-2ed7-11ef-a183-99ad05e145f0":[["転倒を予防するため、通路を明るくした。","为防止跌倒，我们把通道照亮了。"],["道具の故障を予防するため、月に一度点検した。","为预防工具故障，我们每月检查一次。"]],"v-0c49d1aa-2ed7-11ef-a183-99ad05e145f0":[["妹をおだてて荷造りを手伝わせた。","我说了几句好话哄妹妹帮忙收拾行李。"],["いくらおだてられても、無理な役は引き受けない。","无论别人怎么恭维，我都不会接下做不了的差事。"]],"v-0ba781d4-2ed7-11ef-a183-99ad05e145f0":[["先生が来るまで教室で自習した。","老师来之前，我在教室里自习。"],["自習の時間に、昨日間違えた問題を解いた。","自习时我重做了昨天答错的题。"]],"v-49c5acfa-b061-11ef-b775-e7560ea47657":[["祖母の考え方に感化され、古い物を大切にするようになった。","受奶奶的想法影响，我开始珍惜旧物。"],["近所の職人に感化された子どもが、道具作りを始めた。","受附近工匠影响，孩子开始做工具。"]],"v-7a10e89a-679e-11ef-89c9-3b0955f1365d":[["新刊には、祖母が小さいころの町の写真が載っていた。","新刊刊登了奶奶小时候镇上的照片。"],["閉館前に新刊を取り出し、必要なページを写した。","闭馆前，我取出新刊，抄了需要的页面。"]],"v-7a1129f4-679e-11ef-89c9-3b0955f1365d":[["職人は技巧を使って、見本と同じ形を作った。","工匠用技法做出了和样品一样的形状。"],["説明を聞いたあと、技巧の扱いを練習した。","听完讲解后，我练习了如何运用技法。"]],"v-0ce9a28e-2ed7-11ef-a183-99ad05e145f0":[["落ち葉が積もる場所では土がよく肥える。","落叶堆积处的土壤容易变肥沃。"],["毎日絵を見るうちに、少しずつ目が肥えた。","天天看画，我的鉴赏力逐渐提高了。"]],"v-0c47252c-2ed7-11ef-a183-99ad05e145f0":[["朝の静かなうちに旅先へ向かった。","趁早上安静，我朝旅行地出发。"],["撮影した写真を見返すと、夕方の旅先は朝とは違って見えた。","回看照片时，我发现傍晚的旅行地看起来与清晨不同。"]],"v-0c3270aa-2ed7-11ef-a183-99ad05e145f0":[["子どもの出生を知らせる手紙が届いた。","报孩子出生的信寄到了。"],["資料に出生の年月が記されていた。","材料上记载了出生年月。"]],"v-0ce1d70c-2ed7-11ef-a183-99ad05e145f0":[["道具の配置が作業の目的に適っている。","工具的摆放符合工作的目的。"],["荷物を分けて運ぶのは理に適った方法だ。","把物品分开搬是合乎道理的做法。"]],"v-0bfecf0c-2ed7-11ef-a183-99ad05e145f0":[["兄は大学に在学中、町の記録を集めた。","哥哥在大学就读期间收集了镇里的记录。"],["在学していることを示す書類を提出した。","我提交了在读证明。"]],"v-0b8d2d3e-2ed7-11ef-a183-99ad05e145f0":[["冷房を入れると、部屋がすぐ涼しくなった。","一开空调制冷，房间马上凉了下来。"],["夜は冷房を弱くして眠った。","夜里我把制冷调弱后睡了。"]],"v-7a143ef0-679e-11ef-89c9-3b0955f1365d":[["湿気が入らないよう、容器を密閉した。","为了不进潮气，我把容器密封了。"],["密閉した瓶に日付を書いた。","我在密封的瓶子上写了日期。"]],"v-0bf6bc90-2ed7-11ef-a183-99ad05e145f0":[["朝は海水浴のため、玄関をいつもより早く出た。","早上为了海水浴，我比往常更早出门。"],["出発前に、海水浴に必要な物を一つずつ確認した。","出发前，我逐一核对了海水浴需要的东西。"]],"v-0bd0f7f8-2ed7-11ef-a183-99ad05e145f0":[["会場の係に、写しを受け取る場所を尋ねた。","我问会场工作人员到哪儿领副本。"],["帰宅してから、写しを家族にも見せた。","回家后，我也给家人看了副本。"]],"v-0bf5cc2c-2ed7-11ef-a183-99ad05e145f0":[["弱い火で加熱してから、鍋を下ろした。","用小火加热后，我把锅端了下来。"],["加熱しすぎると布の色が変わる。","加热过度，布的颜色会变。"]],"v-7a185e0e-679e-11ef-89c9-3b0955f1365d":[["春先が迫り、店は準備で慌ただしくなった。","初春临近，店里忙着做准备。"],["家族と話し合い、旅行は春先にしようと決めた。","和家人商量后，我们决定把旅行安排在初春。"]],"v-0c244106-2ed7-11ef-a183-99ad05e145f0":[["今年の来場者数は前年を下回った。","今年的到场人数低于去年。"],["修理費が見積もりを下回り、少しお金が残った。","维修费低于估价，剩下了一点钱。"]],"v-0bf3f5be-2ed7-11ef-a183-99ad05e145f0":[["家族で育児を分担している。","全家分担育儿任务。"],["育児のため仕事の時間を短くした。","为了照顾孩子，我缩短了工作时间。"]],"v-0c2461fe-2ed7-11ef-a183-99ad05e145f0":[["数年分を並べて、家計がどう変わったか比べた。","我把好几年的数据排在一起，比较家庭收支如何变化。"],["会議で家計を確認し、次の予定を決めた。","会上确认了家庭收支，随后定下下一项安排。"]],"v-7a1abc62-679e-11ef-89c9-3b0955f1365d":[["申込書の裏面にも記入欄があった。","申请表背面也有填写栏。"],["古い写真の裏面に、撮影者の名前が書かれていた。","老照片背面写有拍摄者的名字。"]],"v-e3286a86-4d22-11f1-8acd-1921b1dbb6e1":[["話が込み入ってきたので、紙に関係を描いた。","事情变复杂了，我在纸上画出了各方关系。"],["込み入った手続きは窓口で説明してもらった。","复杂的手续，我请窗口人员讲解。"]],"v-c2b5b654-4d23-11f1-8acd-1921b1dbb6e1":[["嵐の翌日、浜に木箱が流れ着いた。","风暴次日，一个木箱漂到了海滩。"],["遠くの島から流れ着いた瓶を拾った。","我捡起一个从远岛漂来的瓶子。"]],"v-7a1bad98-679e-11ef-89c9-3b0955f1365d":[["木の札は両面に色が塗ってある。","木牌的两面都涂了颜色。"],["新しい方法を費用と使いやすさの両面から比べた。","我从成本和易用性两方面比较了新方法。"]],"v-7a1d0d3c-679e-11ef-89c9-3b0955f1365d":[["近所で道具の貸し借りをしていた。","邻居之间互相借用工具。"],["お金の貸し借りは帳面に記した。","钱的借入借出都记在账本上。"]],"v-0b857e54-2ed7-11ef-a183-99ad05e145f0":[["薄く切った大根を塩に漬けた。","我把切薄的萝卜腌在盐里。"],["梅を漬けるため、大きな瓶を洗った。","为了腌梅子，我洗了个大玻璃罐。"]],"v-0c684cca-2ed7-11ef-a183-99ad05e145f0":[["治ったと思っていた痛みが再発した。","以为痊愈的疼痛又发作了。"],["事故の再発を防ぐため、手順を見直した。","为了防止事故再次发生，我们重新检查了流程。"]],"v-025ac47e-4d25-11f1-8acd-1921b1dbb6e1":[["彼は生まれ持った音感を練習で磨いた。","他通过练习磨炼天生的音感。"],["生まれ持った特徴がすべてを決めるわけではない。","与生俱来的特征并不决定一切。"]],"v-0ce8c3a0-2ed7-11ef-a183-99ad05e145f0":[["判を濡らさないよう、箱に入れてから運んだ。","我把印章装进盒子才搬运，免得弄湿。"],["棚から古い判を取り出し、別の場所へ移した。","我从架子上取下旧的印章，移到了别处。"]],"v-7a298c38-679e-11ef-89c9-3b0955f1365d":[["朝は実地のため、玄関をいつもより早く出た。","早上为了实地作业，我比往常更早出门。"],["出発前に、実地に必要な物を一つずつ確認した。","出发前，我逐一核对了实地作业需要的东西。"]],"v-8a03110c-1b98-11f0-a55c-bfbb3fc5c3f5":[["新しい住民とも関わり合いながら行事を続けた。","我们与新居民一同参与，延续了活动。"],["この研究では水と土がどう関わり合うかを調べた。","这项研究考察水和土如何相互影响。"]],"v-49ccdf8e-b061-11ef-b775-e7560ea47657":[["遠くから来た同郷のために、駅まで迎えに行った。","我到车站迎接远道而来的同乡。"],["同郷と話して、以前知らなかった話を聞けた。","与同乡交谈后，我听说了以前不知道的事。"]],"v-7a2b3254-679e-11ef-89c9-3b0955f1365d":[["調べ始める前に、自然界の意味を資料で確かめた。","开始调查前，我查阅材料确认了自然界的含义。"],["説明では、自然界について具体的な事例を挙げた。","讲解时，我们举了有关自然界的具体例子。"]],"v-f215b5a0-ce4b-11ef-9903-4d5df4b0073e":[["調べ始める前に、人工知能の意味を資料で確かめた。","开始调查前，我查阅材料确认了人工智能的含义。"],["説明では、人工知能について具体的な事例を挙げた。","讲解时，我们举了有关人工智能的具体例子。"]],"v-4a63b2ec-b061-11ef-b775-e7560ea47657":[["聞き取りの結果は、記録の数字と乖離していた。","访谈结果与记录里的数字有偏差。"],["理想と現実の乖離を小さくしたい。","我想缩小理想与现实的差距。"]],"v-49ce1d4a-b061-11ef-b775-e7560ea47657":[["入力が正しくても、同じ番号が出ることは有り得る。","即使输入正确，也有可能出现同一号码。"],["この規模の変更を一日で終えるなど、有り得ない。","这种规模的改动不可能一天做完。"]],"v-0b9bbf20-2ed7-11ef-a183-99ad05e145f0":[["橋が工事中なので回り道をした。","桥在施工，我绕了远路。"],["急がない日は、川沿いを回り道して帰る。","不赶时间时，我会绕到河边回家。"]],"v-0ca0c550-2ed7-11ef-a183-99ad05e145f0":[["犬の尾にはふさふさと毛が生えていた。","狗尾巴上的毛浓密蓬松。"],["祖父は若いころ髪がふさふさだった。","爷爷年轻时头发很浓密。"]],"v-49cebcaa-b061-11ef-b775-e7560ea47657":[["昔の資料には夜勤の様子が細かく書かれていた。","旧资料细致地写了夜班的情况。"],["夜勤のことを祖父から聞き、覚えている話を記録した。","我听爷爷讲了夜班，把记得的内容写下来。"]],"v-7a30b544-679e-11ef-89c9-3b0955f1365d":[["駅の南側に自転車置き場を新設した。","车站南侧新建了自行车停车处。"],["相談窓口を新設する案が通った。","增设咨询窗口的提案通过了。"]],"v-0c390bae-2ed7-11ef-a183-99ad05e145f0":[["面接のあとで最終選考があった。","面试后进入最终选拔。"],["選考の結果は来週、書面で知らせる。","选拔结果下周以书面形式告知。"]],"v-0ccd56a6-2ed7-11ef-a183-99ad05e145f0":[["今日は普段より早く出社した。","今天我比平时早到公司。"],["大雪で出社が遅れた。","因为大雪，我上班迟到了。"]],"v-0be806c8-2ed7-11ef-a183-99ad05e145f0":[["梅雨に入り、部屋がじめじめする。","进入梅雨季后，房间湿漉漉的。"],["じめじめした気分を変えようと散歩した。","为了排解阴郁的心情，我出门散了步。"]],"v-0c7e3332-2ed7-11ef-a183-99ad05e145f0":[["二つの案について班で討論した。","我们小组就两个方案展开了讨论。"],["討論のあと、反対意見も紙にまとめた。","讨论结束后，我们也把反对意见整理在纸上。"]],"v-0bfd04e2-2ed7-11ef-a183-99ad05e145f0":[["机を片付けると部屋が広々とした。","收拾掉桌子后，房间宽敞了。"],["丘の上からは広々とした畑が見える。","从山丘上可以看到辽阔的田地。"]],"v-0c1694fc-2ed7-11ef-a183-99ad05e145f0":[["夕方は縁側で風に当たって涼んだ。","傍晚我坐在廊边吹风乘凉。"],["坂を上ったあと、木陰でしばらく涼んだ。","上完坡后，我在树荫下凉快了一会儿。"]],"v-b92bbd02-692e-11ef-95f0-b30e867324a9":[["午後は在宅しているので、荷物を受け取れる。","下午我在家，可以收货。"],["今月から在宅勤務の日が増えた。","从本月起，居家办公的日子变多了。"]],"v-7a37cdd4-679e-11ef-89c9-3b0955f1365d":[["棚の直下にコンセントがあった。","架子正下方有个电源插座。"],["橋の直下は流れが速かった。","桥正下方的水流很急。"]],"v-0c16f97e-2ed7-11ef-a183-99ad05e145f0":[["日差しでゴムの老化が進んだ。","日晒加速了橡胶老化。"],["木の老化に伴い、表面に細い割れ目が出た。","木材老化后，表面出现了细裂缝。"]],"v-0cdee312-2ed7-11ef-a183-99ad05e145f0":[["数年分を並べて、蓄えがどう変わったか比べた。","我把好几年的数据排在一起，比较积蓄如何变化。"],["会議で蓄えを確認し、次の予定を決めた。","会上确认了积蓄，随后定下下一项安排。"]],"v-0bd7f1c0-2ed7-11ef-a183-99ad05e145f0":[["重い本は宅配で送った。","重书用快递送到了家。"],["この店では注文品を翌日に宅配してくれる。","这家店会在次日把订购的东西配送到家。"]],"v-0c3f483e-2ed7-11ef-a183-99ad05e145f0":[["入会についての問い合わせを、担当窓口で受け付けた。","办事窗口受理了有关入会的咨询。"],["入会の手続きがどのように変わったか、案内を読んだ。","我读了指引，了解入会的手续有何变化。"]],"v-49d333a2-b061-11ef-b775-e7560ea47657":[["模様の中に金色の糸を織り込んだ。","我在花样中织入了金线。"],["来場者から聞いた話を発表に織り込んだ。","我把访客讲述的内容穿插进了报告。"]],"v-0bf90946-2ed7-11ef-a183-99ad05e145f0":[["水道工事のため、店は二日間休業した。","因为水管施工，商店停业两天。"],["休業の知らせを扉に貼った。","我把停业通知贴在门上。"]],"v-49d3aa26-b061-11ef-b775-e7560ea47657":[["目算では、棚を二台作るだけの板がある。","估算下来，木板够做两个架子。"],["三日で終わるという目算が外れた。","原以为三天能做完，结果估算错了。"]],"v-0c0ef616-2ed7-11ef-a183-99ad05e145f0":[["この水車は雨の多い季節に発電する。","这个水轮在多雨季节发电。"],["発電に使った燃料の量を記録した。","我们记录了发电所用的燃料量。"]],"v-0bf5308c-2ed7-11ef-a183-99ad05e145f0":[["汁の塩分を抑えるため、味付けを最後にした。","为控制汤的盐分，我最后才调味。"],["海から離れると、川の水の塩分は下がった。","远离大海后，河水盐分降低了。"]],"v-0c56d922-2ed7-11ef-a183-99ad05e145f0":[["変更の申請を一括で受け付けた。","我们统一受理了变更申请。"],["五か月分の料金を一括で払った。","我一次付了五个月的费用。"]],"v-0c805892-2ed7-11ef-a183-99ad05e145f0":[["写真の大会で妹が入賞した。","妹妹在摄影比赛中获奖了。"],["入賞した作品を駅前に展示した。","获奖作品在车站前展出。"]],"v-7a3ffc66-679e-11ef-89c9-3b0955f1365d":[["到着時刻から逆算して、出発の時間を決めた。","从到达时间倒推，定下了出发时间。"],["必要な枚数から、元の紙の大きさを逆算した。","我从所需张数倒算出原纸大小。"]],"v-4a641a66-b061-11ef-b775-e7560ea47657":[["文系に興味を持ち、入門書を一冊選んだ。","我对文科产生了兴趣，选了一本入门书。"],["公開講座で文系について学び、以前とは違う見方をするようになった。","在公开课上学了文科后，我开始有不同的看法。"]],"v-0ce5eaae-2ed7-11ef-a183-99ad05e145f0":[["春から駅に近い部屋に入居した。","春天起我搬进了靠近车站的房间。"],["入居前に窓が開くか確認した。","入住前，我确认窗户能不能开。"]],"v-7a425a60-679e-11ef-89c9-3b0955f1365d":[["波風が収まるまで船を出さなかった。","风浪平息前，我们没让船出航。"],["近所に波風を立てないよう、工事の前に説明した。","为了不在邻里间引起风波，我们在施工前作了说明。"]],"v-472c5cc4-a0bb-11ef-9eca-75d1f1bae144":[["理系に興味を持ち、入門書を一冊選んだ。","我对理工科产生了兴趣，选了一本入门书。"],["公開講座で理系について学び、以前とは違う見方をするようになった。","在公开课上学了理工科后，我开始有不同的看法。"]],"v-92cb3996-4daa-11f1-b81c-a57127b838b2":[["水で洗い出した砂をふるいにかけた。","我用筛子筛了冲洗出来的沙。"],["古い手順の問題点を一つずつ洗い出した。","我们逐项查明了旧流程的问题。"]],"v-7a4795d4-679e-11ef-89c9-3b0955f1365d":[["皆で落語の面白さについて話した。","大家聊了落语有意思的地方。"],["落語に関する展示を見て、今まで知らなかったことを一つ覚えた。","看了有关落语的展览，我记住了一件从前不知道的事。"]],"v-0b76d0f2-2ed7-11ef-a183-99ad05e145f0":[["この建物内での喫煙は禁止です。","本楼内禁止吸烟。"],["健康診断で喫煙の習慣について聞かれた。","体检时我被问及吸烟习惯。"]],"v-0cb3ae7c-2ed7-11ef-a183-99ad05e145f0":[["晴れた週末に来場者が急増した。","晴朗的周末，到场人数急剧增加。"],["問い合わせの急増に備え、窓口を増やした。","为应对咨询量猛增，我们增加了窗口。"]],"v-c7becfe2-4dae-11f1-b81c-a57127b838b2":[["集めた数字を表にインプットした。","我把收集的数字输入了表格。"],["名前をインプットすると、予約が表示された。","输入姓名后，屏幕显示了预约。"]],"v-63f6413c-4db0-11f1-b81c-a57127b838b2":[["厚い壁を通ると電波が減衰する。","穿过厚墙时，无线电波会衰减。"],["振動が減衰するまでの時間を測った。","我测了振动衰减所用的时间。"]],"v-0bfc7342-2ed7-11ef-a183-99ad05e145f0":[["皆で碁の面白さについて話した。","大家聊了围棋有意思的地方。"],["碁に関する展示を見て、今まで知らなかったことを一つ覚えた。","看了有关围棋的展览，我记住了一件从前不知道的事。"]],"v-0c8dffd8-2ed7-11ef-a183-99ad05e145f0":[["財布を忘れた友人の分を立て替えた。","我替忘带钱包的朋友先付了钱。"],["送料は私が立て替えておく。","邮费我先垫付。"]],"v-0c7efea2-2ed7-11ef-a183-99ad05e145f0":[["申込書と一緒に写真を同封した。","我把照片和申请表一起装进了信封。"],["返信用の封筒を同封しておきます。","我会随信附上回信用的信封。"]],"v-0be3e14c-2ed7-11ef-a183-99ad05e145f0":[["夕刊には、祖母が小さいころの町の写真が載っていた。","晚报刊登了奶奶小时候镇上的照片。"],["閉館前に夕刊を取り出し、必要なページを写した。","闭馆前，我取出晚报，抄了需要的页面。"]],"v-49e11f44-b061-11ef-b775-e7560ea47657":[["秋になって庭の木が結実した。","秋天来了，院里的树结果了。"],["長年の準備が結実し、小さな店を開けた。","多年准备终于有了成果，我开了家小店。"]],"v-0c27ff4e-2ed7-11ef-a183-99ad05e145f0":[["共働きの両親は交代で迎えに来た。","双职工父母轮流来接。"],["二人で働き始め、共働きになった。","两人都开始工作，成了双职工。"]],"v-b3105af2-4def-11f1-92ad-a9d8dc6c1b5c":[["似た地域の記録から、変化の原因を類推した。","我们根据相似地区的记录类推变化原因。"],["一例だけで他の場合を類推するのは難しい。","只凭一个例子，很难推测其他情况。"]],"v-0ba8e09c-2ed7-11ef-a183-99ad05e145f0":[["経験のある職員を案内係の責任者に就けた。","我们让有经验的职员担任引导组负责人。"],["新しい部署の長に彼女を就けることが決まった。","已经决定任命她担任新部门主管。"]],"v-49e450b0-b061-11ef-b775-e7560ea47657":[["夏期が迫り、店は準備で慌ただしくなった。","夏季临近，店里忙着做准备。"],["家族と話し合い、旅行は夏期にしようと決めた。","和家人商量后，我们决定把旅行安排在夏季。"]],"v-0bec744c-2ed7-11ef-a183-99ad05e145f0":[["工房を始めたばかりのころは、ほとんどもうからなかった。","工坊刚开时，几乎不赚钱。"],["材料費を下げても、売れなければもうからない。","即使降低材料费，卖不出去也赚不到钱。"]],"v-49e5c9fe-b061-11ef-b775-e7560ea47657":[["寒くなると、この種は土の中で休眠する。","天气一冷，这个物种就在土里休眠。"],["人手不足で、町の計画は長く休眠していた。","由于人手不足，小镇的计划长期搁置。"]],"v-0c8d18ca-2ed7-11ef-a183-99ad05e145f0":[["ご来場の際は、受付でお名前をお伝えください。","到场时请在接待处告知姓名。"],["雨でも多くの人が来場した。","虽然下雨，还是有许多人到场。"]],"v-fef2b252-4df0-11f1-92ad-a9d8dc6c1b5c":[["保存の途中でソフトがクラッシュした。","保存到一半，软件崩溃了。"],["クラッシュに備えて、別の場所にもデータを保存した。","为防程序崩溃，我把数据也保存到了另一处。"]],"v-0c0a7af0-2ed7-11ef-a183-99ad05e145f0":[["引用では途中を「中略」とした。","引用时，中间部分写成了“中略”。"],["中略した箇所には、作業の細かい手順が書かれていた。","省略的部分原本写着详细操作步骤。"]],"v-0c3c0656-2ed7-11ef-a183-99ad05e145f0":[["閉店前に値引きされたパンを買った。","我在打烊前买了打折面包。"],["値引きの幅は品物によって違う。","不同商品的降价幅度不一样。"]],"v-0c81f648-2ed7-11ef-a183-99ad05e145f0":[["玄関の扉の塗料が所々剝げていた。","门厅门上的油漆有几处剥落了。"],["何年も日が当たり、看板の色が剝げた。","招牌晒了多年，已经褪色。"]],"v-0bf94b4a-2ed7-11ef-a183-99ad05e145f0":[["近所の店が求人を出した。","附近的商店发了招聘启事。"],["求人の紙を見て、店に電話した。","我看了招聘启事，给店里打了电话。"]],"v-0c211d6e-2ed7-11ef-a183-99ad05e145f0":[["煮た芋は手でも簡単に皮が剝ける。","煮熟的芋头用手也容易剥皮。"],["長く歩いたあと、かかとの皮が剝けていた。","走了很久以后，脚后跟的皮磨掉了。"]],"v-0c453d02-2ed7-11ef-a183-99ad05e145f0":[["会場には名産が置かれ、実際に手に取ることができた。","会场摆着名产，人们可以亲手拿起来看。"],["持ち帰った名産を家族に見せ、どこで見つけたか説明した。","我把带回来的名产给家人看，讲了是在哪儿发现的。"]],"v-6d645bc0-b061-11ef-b775-e7560ea47657":[["見学のあとで、生産者の仕事について質問した。","参观后，我就生产者的工作提出了问题。"],["生産者が実際に作業している様子を、少し離れて見た。","我站远一点观察了生产者实际工作的样子。"]],"v-0beb0b5c-2ed7-11ef-a183-99ad05e145f0":[["濡れたまま置いた釘がさびた。","钉子湿着放在那里，生锈了。"],["自転車がさびないよう、軒下に入れた。","为了不让自行车生锈，我把它推到屋檐下。"]],"v-0c6acaa4-2ed7-11ef-a183-99ad05e145f0":[["式典で先生から励ましのお言葉を賜った。","典礼上，我得到了老师的勉励。"],["皆様からご支援を賜り、展示を開くことができました。","承蒙各位支持，展览得以举办。"]],"v-49f43e08-b061-11ef-b775-e7560ea47657":[["初秋が迫り、店は準備で慌ただしくなった。","初秋临近，店里忙着做准备。"],["家族と話し合い、旅行は初秋にしようと決めた。","和家人商量后，我们决定把旅行安排在初秋。"]],"v-b9e71aa2-692e-11ef-95f0-b30e867324a9":[["その写真が、証言の内容を裏付けた。","那张照片佐证了证词的内容。"],["予測を裏付ける記録が見つからなかった。","没有发现支持预测的记录。"]],"v-0c339430-2ed7-11ef-a183-99ad05e145f0":[["少子化の変化を調べるため、過去十年の記録を表にした。","为了考察少子化的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、少子化にどのような傾向があるか説明した。","我们用调查结果解释了少子化有什么趋势。"]],"v-0c03ce6c-2ed7-11ef-a183-99ad05e145f0":[["小さな変更でも、省エネに影響が出ないか先に確かめた。","即使是小变动，我们也先确认会不会影响节能。"],["実際に使った人から、省エネについて意見を聞いた。","我们向实际使用者征求了对节能的意见。"]],"v-49fa3042-b061-11ef-b775-e7560ea47657":[["遠くから来た語り手のために、駅まで迎えに行った。","我到车站迎接远道而来的讲述者。"],["語り手と話して、以前知らなかった話を聞けた。","与讲述者交谈后，我听说了以前不知道的事。"]],"v-88984066-4e79-11f1-beee-f9338ab5b368":[["雨の予報を受け、出発を一時間繰り上げた。","得知预报有雨，我们提前一小时出发。"],["空きが出たので、待機中の一人を繰り上げた。","出现空缺后，我们递补了一名候补者。"]],"v-49fd1532-b061-11ef-b775-e7560ea47657":[["新しい資料が出たので、結論を再検討した。","有了新材料，我们重新研究了结论。"],["費用を計算し直し、案を再検討する。","我们重新计算费用后再审议方案。"]],"v-0bc7c93a-2ed7-11ef-a183-99ad05e145f0":[["温暖化の変化を調べるため、過去十年の記録を表にした。","为了考察气候变暖的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、温暖化にどのような傾向があるか説明した。","我们用调查结果解释了气候变暖有什么趋势。"]],"v-0c387018-2ed7-11ef-a183-99ad05e145f0":[["整理券は先着二十人に配る。","号码牌发给最先到的二十人。"],["席は先着順で決まった。","座位按先到先得的顺序确定。"]],"v-7a90ca9c-679e-11ef-89c9-3b0955f1365d":[["贈り物の授受について規則を決めた。","我们制定了有关礼物赠受的规则。"],["この授業では、物の授受を表す動詞を比べた。","这堂课比较了表示物品授受的动词。"]],"v-0ca43a1e-2ed7-11ef-a183-99ad05e145f0":[["何度も作り直したが、最後までやり抜いた。","虽然重做了多次，我还是坚持做到了最后。"],["一人でやり抜くつもりだったが、途中で仲間が加わった。","本想独自坚持到底，中途有伙伴加入了。"]],"v-0c2d6fd8-2ed7-11ef-a183-99ad05e145f0":[["住民の高齢化で、坂道の移動が課題になった。","居民老龄化使坡道出行成了问题。"],["高齢化の進み方は、地区によって違う。","不同地区的老龄化进程不同。"]],"v-88d93d96-4e79-11f1-beee-f9338ab5b368":[["計算の結果を表としてアウトプットした。","我把计算结果输出为表格。"],["装置のアウトプットを別の機器で受け取った。","我们用另一台设备接收了装置的输出。"]],"v-7aadb83c-679e-11ef-89c9-3b0955f1365d":[["調べ始める前に、自律神経の意味を資料で確かめた。","开始调查前，我查阅材料确认了自主神经的含义。"],["説明では、自律神経について具体的な事例を挙げた。","讲解时，我们举了有关自主神经的具体例子。"]],"v-7aae9568-679e-11ef-89c9-3b0955f1365d":[["誰もいない部屋の電気を消して節電した。","我关掉没人的房间里的灯，节省用电。"],["節電のため、明るい時間に作業した。","为省电，我趁天亮时工作。"]],"v-7ab64c72-679e-11ef-89c9-3b0955f1365d":[["夕方は乗り換え口が込み合う。","傍晚换乘口会很拥挤。"],["店が込み合っていて、注文まで時間がかかった。","店里很挤，等了好久才点上单。"]],"v-0ce244c6-2ed7-11ef-a183-99ad05e145f0":[["試料に塩を少量添加した。","我向样品中添加了少量盐。"],["食品に何が添加されているか表示を読んだ。","我查看了标签，看看食品添加了什么。"]],"v-0bafe05e-2ed7-11ef-a183-99ad05e145f0":[["異動する友人の送別会を開いた。","我们为调动工作的朋友开了送别会。"],["送別の品として、小さな地図を贈った。","我送了一张小地图作为送别礼物。"]],"v-7a206194-4e79-11f1-beee-f9338ab5b368":[["気温と水の使用量に相関があった。","气温和用水量有关联。"],["相関があるからといって、原因だとは限らない。","有相关性，并不能断定有因果关系。"]],"v-0c6b1f40-2ed7-11ef-a183-99ad05e145f0":[["遠くから来た客を温かい汁物で持て成した。","我们用热汤款待远道而来的客人。"],["母は友人を庭で持て成す準備をした。","妈妈准备在院子里招待朋友。"]],"v-0c6f60c8-2ed7-11ef-a183-99ad05e145f0":[["兄は野菜の小売りを始めた。","哥哥开始做蔬菜零售。"],["この店は卸売りも小売りも行う。","这家店既做批发也做零售。"]],"v-4a2f9f02-b061-11ef-b775-e7560ea47657":[["小さな字を誤読して、違う番号を書いた。","我看错了小字，写了另一个号码。"],["誤読を防ぐため、数字の間隔を広げた。","为防止误读，我增大了数字之间的距离。"]],"v-4a6387b8-b061-11ef-b775-e7560ea47657":[["鉛筆の芯には黒鉛が使われている。","铅笔芯用到了石墨。"],["黒鉛の粉で紙が黒く汚れた。","石墨粉把纸弄黑了。"]],"v-4a641188-b061-11ef-b775-e7560ea47657":[["古い写真を修整し、傷を目立たなくした。","我修了旧照片，把划痕修得不显眼。"],["明るさだけ修整して、色は残した。","只修了亮度，颜色保留原样。"]],"v-88f354a6-4e79-11f1-beee-f9338ab5b368":[["暖かい部屋で野菜を促成栽培した。","我们在暖房里促成栽培蔬菜。"],["農家は収穫を早めるために、促成栽培を試した。","农户为了提早收获，试了促成栽培。"]],"v-0c75d62e-2ed7-11ef-a183-99ad05e145f0":[["会場の係に、前売りを受け取る場所を尋ねた。","我问会场工作人员到哪儿领预售票。"],["帰宅してから、前売りを家族にも見せた。","回家后，我也给家人看了预售票。"]],"v-0c2fc8aa-2ed7-11ef-a183-99ad05e145f0":[["兄は子どものころから友達にもてた。","哥哥从小就在朋友中很受欢迎。"],["面白い話をする彼女は、どの集まりでももてる。","她会讲有趣的话，在任何聚会上都受欢迎。"]],"v-0bde1b54-2ed7-11ef-a183-99ad05e145f0":[["犬は雷の音を怖がって机の下に入った。","狗害怕雷声，钻到了桌子底下。"],["子どもが暗い道を怖がるので、手をつないだ。","孩子怕走暗路，我就牵着他的手。"]],"v-0ba5e8a6-2ed7-11ef-a183-99ad05e145f0":[["笑いを殺して、会議が終わるまで待った。","我忍住笑，等会议结束。"],["獣が息を殺して草むらに潜んでいた。","野兽屏住呼吸，藏在草丛中。"]],"v-0cecc068-2ed7-11ef-a183-99ad05e145f0":[["答えが見えないよう、紙を裏返して伏せた。","为了不让人看见答案，我把纸反扣过来。"],["相談者の名前は伏せたまま報告した。","我在报告时没有公开咨询者的姓名。"]],"v-0c5792e0-2ed7-11ef-a183-99ad05e145f0":[["重い袋を玄関まで引きずっていった。","我把沉重的袋子一路拖到门厅。"],["昨日の失敗を今日まで引きずっている。","昨天的失败让我到今天还耿耿于怀。"]],"v-0b96ac6a-2ed7-11ef-a183-99ad05e145f0":[["長い話し合いの末に、計画がまとまった。","经过长时间讨论，计划定下来了。"],["資金がまとまったので、修理を頼んだ。","钱凑齐了，我便委托了维修。"]],"v-0c11daa2-2ed7-11ef-a183-99ad05e145f0":[["同じ約束を三度忘れた兄に呆れた。","哥哥同一个约定忘了三次，我真拿他没办法。"],["現地の手際の悪さには皆が呆れていた。","现场做事那么拖沓，大家都觉得无语。"]],"v-f2eb2410-4b54-11f1-a630-0ddc817ad47e":[["暗がりの人影を見て目を見開いた。","看到暗处的人影，我睁大了眼睛。"],["子どもは目を見開いて、仕掛けが動くのを見ていた。","孩子睁大眼睛看机关运转。"]],"v-0c768aec-2ed7-11ef-a183-99ad05e145f0":[["父は細い糸で人形を操った。","爸爸用细线操纵木偶。"],["彼女は三つの言語を巧みに操る。","她熟练运用三种语言。"]],"v-0cb74e56-2ed7-11ef-a183-99ad05e145f0":[["泣いている妹の所へ駆け寄った。","我跑到哭着的妹妹身边。"],["迎えが見えると、子どもたちは一斉に駆け寄った。","一看到来接的人，孩子们都跑了过去。"]],"v-0c46d162-2ed7-11ef-a183-99ad05e145f0":[["用件を伝えると、男は静かに立ち去った。","交代完事情，男子悄悄离开了。"],["会場を立ち去る前に忘れ物を確かめた。","离开会场前，我确认了有没有遗忘物品。"]],"v-0cee39de-2ed7-11ef-a183-99ad05e145f0":[["風で扉が閉まり、倉庫に閉じ込められた。","风把门吹上，我被关在仓库里了。"],["誤って猫を押し入れに閉じ込めた。","我不小心把猫关进了壁橱。"]],"v-0c51248c-2ed7-11ef-a183-99ad05e145f0":[["海が見えた途端、子どもたちははしゃいだ。","孩子们一看到大海就兴奋起来。"],["はしゃぎすぎて、帽子を風に飛ばされた。","我兴奋过了头，帽子被风吹跑了。"]],"v-0c646362-2ed7-11ef-a183-99ad05e145f0":[["机の上には、頼んだ書類が見当たらなかった。","桌上没看到我要的文件。"],["地図を広げても、この細い道は見当たらない。","摊开地图也找不到这条窄路。"]],"v-0bd2be80-2ed7-11ef-a183-99ad05e145f0":[["峠の向こうから太陽が昇った。","太阳从山口另一侧升了起来。"],["彼は若くして工場長の地位に昇った。","他年纪轻轻就升到了厂长的位置。"]],"v-0c5cf384-2ed7-11ef-a183-99ad05e145f0":[["長く使った靴のひもが緩んだ。","穿了很久的鞋，鞋带松开了。"],["冗談が出ると、会議の緊張が緩んだ。","有人开了个玩笑，会议的紧张气氛缓和了。"]],"v-0c8aa522-2ed7-11ef-a183-99ad05e145f0":[["戦が古い王国を滅ぼしたと伝えられている。","据说战争毁灭了那个古老的王国。"],["人間が環境を変え、固有種を滅ぼしてしまった。","人类改变环境，导致特有物种灭绝了。"]],"v-0c60ab28-2ed7-11ef-a183-99ad05e145f0":[["犯人は金を出せと店員を脅した。","犯人威胁店员交钱。"],["兄は冗談で弟を脅したつもりだった。","哥哥原本只是开玩笑吓唬弟弟。"]],"v-0cbc4546-2ed7-11ef-a183-99ad05e145f0":[["彼は返事を待たず「ここで終わりだ」と言い放った。","他没等回应便甩下一句“到此为止”。"],["誰も納得していないのに、彼女は問題ないと言い放った。","明明谁也没被说服，她却断言没有问题。"]],"v-0cb1bcc0-2ed7-11ef-a183-99ad05e145f0":[["犬は寒い夜、飼い主に寄り添って眠った。","寒夜里，狗贴着主人睡了。"],["困っている人に寄り添い、まず話を聞く。","体谅身处困难的人，先听听他们的话。"]],"v-0c0e8898-2ed7-11ef-a183-99ad05e145f0":[["見学のあとで、博士の仕事について質問した。","参观后，我就博士的工作提出了问题。"],["博士が実際に作業している様子を、少し離れて見た。","我站远一点观察了博士实际工作的样子。"]],"v-b9e097a4-692e-11ef-95f0-b30e867324a9":[["昨日のやりとりを思い返し、返事を書き直した。","我回想了昨天的交流，重写了答复。"],["あの日を思い返すと、外の雨音まで覚えている。","回想那天，连外面的雨声我都记得。"]],"v-0beb60f2-2ed7-11ef-a183-99ad05e145f0":[["水が澄んで、川底の石まで見える。","水很清，连河底的石头也能看到。"],["風が止み、鐘の音が澄んで聞こえた。","风停了，钟声听起来格外清晰。"]],"v-0c8a9c6c-2ed7-11ef-a183-99ad05e145f0":[["古い王朝が滅びてからも、建物は残った。","古王朝灭亡后，建筑仍留存下来。"],["生息地がなくなれば、この種は滅びかねない。","栖息地消失，这个物种就可能灭绝。"]],"v-79b2e222-679e-11ef-89c9-3b0955f1365d":[["駅の階段で、父の後ろ姿を見送った。","我在车站楼梯旁目送爸爸的背影。"],["雪道を歩く友人の後ろ姿を写真に撮った。","我拍下了朋友走在雪地上的背影。"]],"v-b9e0901a-692e-11ef-95f0-b30e867324a9":[["旅行が決まって、弟は一日中浮かれていた。","旅行确定后，弟弟一整天都兴高采烈。"],["合格に浮かれて、次の申込期限を忘れた。","我因通过考试而高兴过头，忘了下次报名期限。"]],"v-0bcaf77c-2ed7-11ef-a183-99ad05e145f0":[["見学者は展示された偽物の表面をよく観察した。","参观者仔细观察了展出的仿造品的表面。"],["製作者は、偽物を作った時期と材料を記録していた。","制作者记下了制作仿造品的时间与材料。"]],"v-0bdebb5e-2ed7-11ef-a183-99ad05e145f0":[["道を知っている人に、旧橋の場所を聞き出した。","我向熟悉路的人问出了旧桥的位置。"],["取材では、写真を撮った時期まで聞き出せた。","采访中，我们连拍照的时间也问了出来。"]],"v-0c6b41b4-2ed7-11ef-a183-99ad05e145f0":[["調べ始める前に、次元の意味を資料で確かめた。","开始调查前，我查阅材料确认了维度的含义。"],["説明では、次元について具体的な事例を挙げた。","讲解时，我们举了有关维度的具体例子。"]],"v-0c763d44-2ed7-11ef-a183-99ad05e145f0":[["倒れた木が救助隊の行く手を阻んだ。","倒下的树挡住了救援队的去路。"],["細かすぎる規則が新しい試みを阻んでいる。","过细的规定阻碍了新的尝试。"]],"v-0c53d8e4-2ed7-11ef-a183-99ad05e145f0":[["網にかかった魚が激しくもがいた。","入网的鱼猛烈挣扎。"],["思うように書けず、何日ももがいた。","怎么也写不顺，我苦苦挣扎了好几天。"]],"v-0bcd001c-2ed7-11ef-a183-99ad05e145f0":[["その出来事が古代に与えた影響を、当時の新聞で調べた。","我用当时的报纸查了那件事对古代造成的影响。"],["古代について、昔の資料と最近の研究を読み比べた。","关于古代，我对读了旧材料和近期研究。"]],"v-0c87918e-2ed7-11ef-a183-99ad05e145f0":[["日が暮れても連絡がなく、不安が募った。","天黑了还没消息，我越来越不安。"],["資料の整理を手伝う人を町内で募った。","我们在镇内招募帮忙整理材料的人。"]],"v-0c865094-2ed7-11ef-a183-99ad05e145f0":[["白い鳥が雪に紛れて見えなくなった。","白鸟融入雪景，看不见了。"],["庭の手入れをしているうちに、気が紛れた。","打理着院子，我的烦恼暂时消散了。"]],"v-df1f8ac0-58c5-11f0-942b-0d708af8d6f5":[["この鉢はほっとくと土がすぐ乾く。","这盆植物放着不管，土很快就干。"],["古い箱なら、今はほっといていいよ。","那个旧盒子现在先放着不用管。"]],"v-0c659836-2ed7-11ef-a183-99ad05e145f0":[["説明に冗談を交えると、空気が和らいだ。","讲解里穿插一个笑话，气氛放松了。"],["二人は別れ際に短い言葉を交えた。","两人分别时简短交谈了几句。"]],"v-0c36a1f2-2ed7-11ef-a183-99ad05e145f0":[["工場は十年で大きな変化を遂げた。","工厂在十年间完成了巨大的转变。"],["彼女は試験で見事に雪辱を遂げた。","她在考试中出色地扳回了上次的失利。"]],"v-79b85eb4-679e-11ef-89c9-3b0955f1365d":[["毎月、地図好きの仲間が図書室に集う。","每个月，喜欢地图的人都会聚在图书室。"],["夕方には親族が祖母の家に集った。","傍晚，亲戚们聚到了奶奶家。"]],"v-0cfa8a36-2ed7-11ef-a183-99ad05e145f0":[["後ろから突然声を上げて友人を脅かした。","我突然从背后出声，把朋友吓了一跳。"],["暗がりで弟を脅かすつもりが、先に私が驚いた。","本想在暗处吓弟弟，结果自己先吓了一跳。"]],"v-0cbc12a6-2ed7-11ef-a183-99ad05e145f0":[["先に帰ると言い残して、兄は会場を出た。","哥哥留下一句“我先回去了”，就离开会场。"],["祖母は鍵の置き場所を言い残して旅に出た。","奶奶交代了钥匙放哪儿，便出门旅行了。"]],"v-6cd62b02-b061-11ef-b775-e7560ea47657":[["細い川だからと侮ると、増水時には危険だ。","因为河窄就小看它，涨水时会很危险。"],["相手の実力を侮って、最初の試合に負けた。","我低估了对手，输掉了第一场。"]],"v-0c5b089e-2ed7-11ef-a183-99ad05e145f0":[["拾った犬は、何日かで妹に懐いた。","捡来的狗过了几天就亲近妹妹了。"],["鳥が人に懐くまで、少し距離を取って世話をした。","在鸟亲近人之前，我保持一点距离照料它。"]],"v-0c69b556-2ed7-11ef-a183-99ad05e145f0":[["広い部屋を棚で仕切った。","我用架子隔开了大房间。"],["打ち合わせは経験のある職員が仕切った。","碰头会由一位有经验的职员主持。"]],"v-0cd77244-2ed7-11ef-a183-99ad05e145f0":[["案内人は湿地を守る大切さを説いた。","向导说明了保护湿地的重要性。"],["著者は、疑問を持って記録を読む必要を説く。","作者阐述了带着疑问读记录的必要性。"]],"v-b9db9d9e-692e-11ef-95f0-b30e867324a9":[["十七を三で割り切ることはできない。","十七不能被三整除。"],["終わったことだと割り切って、次の準備にかかった。","我想开了，把过去的事放下，开始准备下一项。"]],"v-0bcc38bc-2ed7-11ef-a183-99ad05e145f0":[["現物を前にすると、写真では分からなかった形状に気づいた。","看到实物后，我察觉到了照片里看不出的形状。"],["二つの試作品を並べ、形状の違いを確かめた。","我们把两个样品并排放置，核对了形状的差异。"]],"v-0c5a412a-2ed7-11ef-a183-99ad05e145f0":[["長い試合のあと、選手は疲れ果てた。","长时间的比赛结束后，选手累坏了。"],["水も食べ物もなく、旅人は山中で力尽きて果てた。","没有水也没有食物，旅人在山中力竭而亡。"]],"v-b9dc299e-692e-11ef-95f0-b30e867324a9":[["鍵を探して家の周りをうろついた。","我在房子周围转来转去找钥匙。"],["道に迷い、同じ角の辺りをうろついていた。","我迷路了，一直在同一个拐角附近徘徊。"]],"v-b9d3c5f6-692e-11ef-95f0-b30e867324a9":[["予定が変わっても、彼女は動じなかった。","安排有变，她也没有慌。"],["突然名前を呼ばれたが、動じずに答えた。","突然被叫到名字，我镇定地回答了。"]],"v-0c50a606-2ed7-11ef-a183-99ad05e145f0":[["水滴が落ちて、宛名の文字がにじんだ。","水滴落下，收件人的字洇开了。"],["彼の短い返事には疲れがにじんでいた。","他简短的答复里流露出疲惫。"]],"v-0bea5522-2ed7-11ef-a183-99ad05e145f0":[["宿に着いて、窓辺の椅子でくつろいだ。","到住处后，我坐在窗边的椅子上放松。"],["食事のあと、家族は庭でくつろいでいた。","吃过饭，全家在院子里悠闲休息。"]],"v-0c782a50-2ed7-11ef-a183-99ad05e145f0":[["点検を怠ったせいで、傷に気づかなかった。","因为疏于检查，我没发现划痕。"],["慣れた作業でも、最後の確認を怠らない。","即使是熟悉的活，我也不省掉最后的检查。"]],"v-79ba818a-679e-11ef-89c9-3b0955f1365d":[["薄い布から窓の形が透けて見えた。","透过薄布能隐约看见窗的形状。"],["白い封筒は、中の文字が透けることがある。","白信封有时会透出里面的字。"]],"v-0c642a64-2ed7-11ef-a183-99ad05e145f0":[["祖父を見習って、使った道具はすぐ戻した。","我学爷爷，用完工具马上归位。"],["先輩の落ち着いた対応を見習いたい。","我想学习前辈冷静处理事情的做法。"]],"v-0c99c85e-2ed7-11ef-a183-99ad05e145f0":[["遊びに行けず、弟はすねて返事をしなかった。","没能出去玩，弟弟闹别扭不回答。"],["席を替わってもらえなかったくらいですねるなよ。","别因为没能换座位就闹别扭啊。"]],"v-0cba606e-2ed7-11ef-a183-99ad05e145f0":[["夜の港の光に見入ってしまった。","我望着夜晚港口的灯光出了神。"],["古い写真に見入って、声をかけられたことに気づかなかった。","我看旧照片看入了神，没注意到有人喊我。"]],"v-0cba137a-2ed7-11ef-a183-99ad05e145f0":[["窓から見える雪山に見とれた。","我望着窗外的雪山看入了迷。"],["妹は職人の素早い手つきに見とれていた。","妹妹被工匠利落的手法吸引住了。"]],"v-0c7e3b66-2ed7-11ef-a183-99ad05e145f0":[["前回の結果を踏まえて、手順を見直した。","我们依据上一次的结果重新审视了流程。"],["会議で出た意見を踏まえ、別の案を作った。","我们参考会上提出的意见做了另一份方案。"]],"v-0cc79392-2ed7-11ef-a183-99ad05e145f0":[["出発まで時間を持て余し、駅前を散歩した。","离出发还有时间没处打发，我就在车站前散了步。"],["大きな機械を買ったが、狭い工房では持て余している。","买了台大机器，可狭小的工坊里用不开。"]],"v-0c64d0f4-2ed7-11ef-a183-99ad05e145f0":[["弟は鍵を返したと言い張った。","弟弟坚持说已经还了钥匙。"],["資料を見せても、彼は数字が違うと言い張った。","即使给他看了材料，他仍坚持说数字不对。"]],"v-0c386802-2ed7-11ef-a183-99ad05e145f0":[["彼女は長く勤めた店との関係を絶った。","她断绝了与工作多年的店的联系。"],["父は退職を機に酒を絶った。","爸爸借退休的机会戒了酒。"]],"v-b9d85f58-692e-11ef-95f0-b30e867324a9":[["壁の色が古びて、かえって部屋になじんでいる。","墙色变旧了，反倒和房间很相衬。"],["駅前の古びた看板を写真に収めた。","我拍下了车站前那块陈旧的招牌。"]],"v-b9d90a7a-692e-11ef-95f0-b30e867324a9":[["白い壁の前では、花の赤が際立つ。","在白墙前，花的红色格外醒目。"],["余計な音を消すと、旋律の美しさが際立った。","去掉多余的声音后，旋律之美更突出。"]],"v-0c702288-2ed7-11ef-a183-99ad05e145f0":[["情勢の変化を調べるため、過去十年の記録を表にした。","为了考察形势的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、情勢にどのような傾向があるか説明した。","我们用调查结果解释了形势有什么趋势。"]],"v-0c84b5ae-2ed7-11ef-a183-99ad05e145f0":[["この川は変化に富み、場所ごとに流れが違う。","这条河变化丰富，各处的水流都不同。"],["海辺の町には、資源に富む沖合があった。","海边小镇附近有资源丰富的海域。"]],"v-0c3aa0c2-2ed7-11ef-a183-99ad05e145f0":[["球を打ち出す角度を少し変えた。","我稍稍改变了击球角度。"],["市は空き家を活用する方針を打ち出した。","市政府提出了利用空置房屋的方针。"]],"v-b9e4f272-692e-11ef-95f0-b30e867324a9":[["針穴を通すため、糸の先を指で細めた。","为了穿针，我用手指把线头捻细了。"],["祖母はまぶしそうに目を細めた。","奶奶仿佛嫌光刺眼，眯起了眼睛。"]],"v-0c798ec2-2ed7-11ef-a183-99ad05e145f0":[["表面を加工した布は水をはじく。","经过表面处理的布能防水。"],["祖父はそろばんをはじいて代金を出した。","爷爷打算盘算出了价钱。"]],"v-6cd8f418-b061-11ef-b775-e7560ea47657":[["相手の勢いにひるんで、言葉が出なかった。","被对方的气势吓住，我说不出话。"],["大きな波が来ても、彼はひるまず櫂を握った。","即使大浪袭来，他也毫不退缩地握住船桨。"]],"v-0be4cf80-2ed7-11ef-a183-99ad05e145f0":[["今、為すべきことは記録を守ることだ。","现在应当做的是保护记录。"],["一人で為し得ることには限りがある。","一个人能做成的事有限。"]],"v-6cdc1b7a-b061-11ef-b775-e7560ea47657":[["職人は道具箱を携えて山の集落へ向かった。","工匠带着工具箱前往山里的村落。"],["二人は調査資料を携えて役場を訪ねた。","两人带着调查材料拜访了地方办事处。"]],"v-0cdea8ac-2ed7-11ef-a183-99ad05e145f0":[["この場所から眺める地形が好きで、何度も足を運んだ。","我喜欢从这里看到的地形，去了好几次。"],["古い写真に写る地形と、今の景色を比べてみた。","我把老照片里的地形和如今的景色作了比较。"]],"v-b8010fcc-4b63-11f1-a630-0ddc817ad47e":[["子犬が庭を駆け巡った。","小狗在院里跑来跑去。"],["店が閉まるという話が町中を駆け巡った。","店要关门的消息传遍了整个镇子。"]],"v-f19dd81e-4b63-11f1-a630-0ddc817ad47e":[["裁判官は証拠に基づいて事件を裁いた。","法官依据证据审理了案件。"],["うわさだけで人を裁いてはいけない。","不能仅凭传闻就给人定罪。"]],"v-0b75281a-2ed7-11ef-a183-99ad05e145f0":[["坂を上ると喉が渇いた。","爬上坡后我口渴了。"],["旅の途中、喉が渇く前に水を飲むようにした。","旅行途中，我注意在口渴前喝水。"]],"v-0c48f154-2ed7-11ef-a183-99ad05e145f0":[["ありふれた木箱に、古い写真が入っていた。","一个普普通通的木盒里放着旧照片。"],["この海岸では、白い石はありふれている。","在这片海岸，白石头随处可见。"]],"v-0c49f4a0-2ed7-11ef-a183-99ad05e145f0":[["雷におびえた犬が机の下に隠れた。","被雷吓坏的狗躲到了桌底。"],["失敗におびえず、一度やってみよう。","别怕失败，先试一次吧。"]],"v-0cd7e882-2ed7-11ef-a183-99ad05e145f0":[["連絡も待たずに先走って、別の会場へ向かった。","我没等通知就贸然去了另一个会场。"],["先走った発表を取り消すことになった。","那条过早发布的消息不得不撤回。"]],"v-0cc03016-2ed7-11ef-a183-99ad05e145f0":[["古い宿だが、手入れが隅々まで行き届いていた。","虽然是老旅馆，但各处都打理得很好。"],["小さい子への配慮が行き届いた展示だった。","这个展览对小孩子的照顾很周到。"]],"v-0c5ef472-2ed7-11ef-a183-99ad05e145f0":[["彼は本物そっくりの札で人を欺いた。","他用酷似真品的牌子欺骗了人。"],["本物らしく塗った木の果物が、見に来た人の目を欺いた。","涂得很逼真的木制水果骗过了来看的人。"]],"v-0c5eec3e-2ed7-11ef-a183-99ad05e145f0":[["職人は技能を使って、見本と同じ形を作った。","工匠用技能做出了和样品一样的形状。"],["説明を聞いたあと、技能の扱いを練習した。","听完讲解后，我练习了如何运用技能。"]],"v-0c69d0f4-2ed7-11ef-a183-99ad05e145f0":[["この部門は製品の検査を司る。","这个部门主管产品检验。"],["呼吸を司る脳の部位について資料を読んだ。","我读了有关大脑中控制呼吸的部位的材料。"]],"v-b9703054-692e-11ef-95f0-b30e867324a9":[["家に入る前に、内装の位置を確認した。","进屋前，我确认了室内装饰的位置。"],["改修の前と後では、内装が大きく変わった。","改修前后，室内装饰变化很大。"]],"v-0c810026-2ed7-11ef-a183-99ad05e145f0":[["三回失敗したが、最後まで粘った。","虽然失败了三次，我还是坚持到最后。"],["この生地は水を入れすぎると粘る。","这种面团加水过多会发黏。"]],"v-0c8f63b4-2ed7-11ef-a183-99ad05e145f0":[["老いても祖母は毎朝庭を一周する。","即使上了年纪，奶奶每天早上也绕院子一圈。"],["老いた犬は段差を慎重に下りた。","年老的狗小心地下了台阶。"]],"v-0cf072f8-2ed7-11ef-a183-99ad05e145f0":[["彼女は上着の裾を翻して走り去った。","她衣摆一扬，跑开了。"],["担当者は資料を見たとたん、反対の意見を翻した。","负责人一看材料，就改变了原先反对的意见。"]],"v-0c45c628-2ed7-11ef-a183-99ad05e145f0":[["静かな風の音が旅の疲れを癒やした。","轻轻的风声消解了旅途的疲倦。"],["友人からの便りが、心の傷を少し癒やしてくれた。","朋友的来信稍稍抚慰了我心里的伤。"]],"v-0c542808-2ed7-11ef-a183-99ad05e145f0":[["代金を誰が払うかでもめた。","大家为谁付钱起了争执。"],["隣同士で境の位置をめぐってもめている。","两家邻居正为分界线的位置争执。"]],"v-b2e9255a-4c63-11f1-9103-c10b58500570":[["混雑を見越して、朝早い便にした。","预料到会拥挤，我选了一早的班次。"],["冬の需要を見越し、秋に材料を確保した。","考虑到冬季的需求，我们在秋天备好了材料。"]],"v-6ce3634e-b061-11ef-b775-e7560ea47657":[["選手はゴールの手前で力尽きた。","选手在终点前耗尽了力气。"],["一晩作業を続けたが、朝方には力尽きた。","我干了一整夜，到清晨终于没力气了。"]],"v-d7d58f52-4c63-11f1-9103-c10b58500570":[["駅の匂いで昔の旅を思い起こした。","车站的气味让我想起旧日的旅行。"],["写真を並べながら、一緒に働いた日々を思い起こした。","我一边摆照片，一边回忆一起工作的日子。"]],"v-0bd50b5e-2ed7-11ef-a183-99ad05e145f0":[["母は港町で生まれ育った。","妈妈在港口小镇出生长大。"],["同じ村で生まれ育った二人は、旅先で再会した。","两个在同一村子出生长大的人在旅途中重逢了。"]],"v-0c359ed8-2ed7-11ef-a183-99ad05e145f0":[["真夏が迫り、店は準備で慌ただしくなった。","盛夏临近，店里忙着做准备。"],["家族と話し合い、旅行は真夏にしようと決めた。","和家人商量后，我们决定把旅行安排在盛夏。"]],"v-b9cd793a-692e-11ef-95f0-b30e867324a9":[["雪が消えてから、歩ける道を見定めた。","等雪化后，我看准了能走的路。"],["店を決める前に、材料の質を見定める。","决定去哪家店前，先看准材料的质量。"]],"v-0caa1114-2ed7-11ef-a183-99ad05e145f0":[["どうぞお体をいとってお過ごしください。","请务必保重身体。"],["彼女は手間をいとわず、箱の中まで調べた。","她不嫌麻烦，把盒子里面也检查了。"]],"v-0cf7717a-2ed7-11ef-a183-99ad05e145f0":[["猫が窓辺で伸びる姿を見て心が和んだ。","看见猫在窗边伸懒腰，我心里放松了。"],["短い冗談で場が和んだ。","一句简短的玩笑让气氛缓和下来。"]],"v-814b3820-4c64-11f1-9103-c10b58500570":[["切羽詰まって、詳しく読む時間もなかった。","情况紧急，连细读的时间都没有。"],["締切が明日に迫り、皆が切羽詰まっていた。","截止日就在明天，大家都急得不行。"]],"v-0cb2ebf4-2ed7-11ef-a183-99ad05e145f0":[["二匹の子犬が芝生で戯れていた。","两只小狗在草坪上嬉戏。"],["子どもたちは波と戯れながら貝殻を集めた。","孩子们一边在浪里玩，一边捡贝壳。"]],"v-0c5642dc-2ed7-11ef-a183-99ad05e145f0":[["弟は今年こそ完走するぞと意気込んだ。","弟弟干劲十足地说今年一定跑完全程。"],["初めは意気込んでいたが、長い坂でペースを落とした。","一开始很有干劲，但在长坡上放慢了速度。"]],"v-0cf40490-2ed7-11ef-a183-99ad05e145f0":[["強い風が古い足場を揺るがした。","大风撼动了旧脚手架。"],["新しい証言が、それまでの見方を揺るがした。","新证词动摇了此前的看法。"]],"v-0c388904-2ed7-11ef-a183-99ad05e145f0":[["荷物を持ち上げたとき、細いひもが千切れた。","提行李时，细绳断了。"],["強い風で旗の端が千切れた。","大风把旗的一角撕掉了。"]],"v-0ce61c86-2ed7-11ef-a183-99ad05e145f0":[["寒さを忍んで、夜明けを待った。","我忍着寒冷等待天亮。"],["人目を忍んで、夜明け前に町を出た。","为避开旁人的眼光，我天亮前离开了镇子。"]],"v-0c612e90-2ed7-11ef-a183-99ad05e145f0":[["議論が行き詰まり、緊張が極まった。","讨论陷入僵局，紧张达到顶点。"],["無断で資料を捨てるとは、失礼極まる行為だ。","擅自扔掉材料，实在太失礼了。"]],"v-b9cd0392-692e-11ef-95f0-b30e867324a9":[["厳しい冬を生き抜いた苗に、新芽が出た。","熬过严冬的幼苗长出了新芽。"],["祖父は戦後の混乱を生き抜いた。","爷爷在战后动荡中活了下来。"]],"v-0c8954e2-2ed7-11ef-a183-99ad05e145f0":[["調べ始める前に、味覚の意味を資料で確かめた。","开始调查前，我查阅材料确认了味觉的含义。"],["説明では、味覚について具体的な事例を挙げた。","讲解时，我们举了有关味觉的具体例子。"]],"v-0ca9284e-2ed7-11ef-a183-99ad05e145f0":[["暗い額が絵の明るさを引き立てる。","深色画框衬托了画的明亮。"],["少量の塩が果物の甘みを引き立てた。","少许盐突出了水果的甜味。"]],"v-74a520ba-58c5-11f0-942b-0d708af8d6f5":[["式では長年の功績をたたえた。","典礼上表彰了多年的功绩。"],["町の人は、橋を守った職人たちをたたえた。","镇上的人赞扬了守护那座桥的工匠。"]],"v-0c734792-2ed7-11ef-a183-99ad05e145f0":[["その出来事が政権に与えた影響を、当時の新聞で調べた。","我用当时的报纸查了那件事对政权造成的影响。"],["政権について、昔の資料と最近の研究を読み比べた。","关于政权，我对读了旧材料和近期研究。"]],"v-0cc5e448-2ed7-11ef-a183-99ad05e145f0":[["転居するかどうか、姉はしばらく思い悩んだ。","姐姐为是否搬家苦恼了一段时间。"],["思い悩むだけでは進まないので、友人に相談した。","光发愁没有进展，我就找朋友商量。"]],"v-79e791c0-679e-11ef-89c9-3b0955f1365d":[["その出来事が幕府に与えた影響を、当時の新聞で調べた。","我用当时的报纸查了那件事对幕府造成的影响。"],["幕府について、昔の資料と最近の研究を読み比べた。","关于幕府，我对读了旧材料和近期研究。"]],"v-0bd149d8-2ed7-11ef-a183-99ad05e145f0":[["鍋が沸いたら火を弱める。","锅开后把火调小。"],["風の力を弱めるために木を植えた。","为了减弱风力，我们栽了树。"]],"v-6cef52c6-b061-11ef-b775-e7560ea47657":[["小さな店だからと見くびっていたが、仕事は見事だった。","我因为店小而小看它，结果人家活干得漂亮。"],["初心者だからといって、相手を見くびってはいけない。","不能因为对方是新手就轻视他。"]],"v-0c7a0cf8-2ed7-11ef-a183-99ad05e145f0":[["皆に褒められ、弟は恥じらって目を伏せた。","大家夸他，弟弟害羞地垂下眼睛。"],["彼女は恥じらうように小さく笑った。","她像是害羞似的轻轻笑了。"]],"v-0cb0e4a8-2ed7-11ef-a183-99ad05e145f0":[["最近の被害に鑑み、点検を増やした。","鉴于最近的损害，我们增加了检查。"],["安全上の問題に鑑みて、会場を変更した。","鉴于安全问题，我们改了会场。"]],"v-1c0e1406-4ce0-11f1-90a9-0fc8163987fc":[["路地が入り組んでいて、地図が役に立たなかった。","小巷纵横交错，地图没派上用场。"],["入り組んだ事情を、担当者が順を追って説明した。","负责人按顺序解释了错综复杂的情况。"]],"v-6cf30fce-b061-11ef-b775-e7560ea47657":[["朝の静かなうちに住処へ向かった。","趁早上安静，我朝栖身处出发。"],["撮影した写真を見返すと、夕方の住処は朝とは違って見えた。","回看照片时，我发现傍晚的栖身处看起来与清晨不同。"]],"v-0c2a4222-2ed7-11ef-a183-99ad05e145f0":[["服装が変わったので、一瞬兄を見違えた。","哥哥换了穿着，我一时没认出来。"],["掃除のあと、部屋は見違えるほど明るくなった。","打扫完以后，房间明亮得像变了样。"]],"v-0c649cec-2ed7-11ef-a183-99ad05e145f0":[["見学者は展示された原型の表面をよく観察した。","参观者仔细观察了展出的原型的表面。"],["製作者は、原型を作った時期と材料を記録していた。","制作者记下了制作原型的时间与材料。"]],"v-0b82469e-2ed7-11ef-a183-99ad05e145f0":[["数年分を並べて、赤字がどう変わったか比べた。","我把好几年的数据排在一起，比较赤字如何变化。"],["会議で赤字を確認し、次の予定を決めた。","会上确认了赤字，随后定下下一项安排。"]],"v-0cba1bae-2ed7-11ef-a183-99ad05e145f0":[["現物を前にすると、写真では分からなかった見栄えに気づいた。","看到实物后，我察觉到了照片里看不出的外观。"],["二つの試作品を並べ、見栄えの違いを確かめた。","我们把两个样品并排放置，核对了外观的差异。"]],"v-0c28e3e6-2ed7-11ef-a183-99ad05e145f0":[["連絡を受けて、職員が現場に駆けつけた。","接到消息后，工作人员赶到现场。"],["友人の発表を聞こうと、仕事のあとで会場へ駆けつけた。","为了听朋友发言，我下班后赶到了会场。"]],"v-0c6a0a88-2ed7-11ef-a183-99ad05e145f0":[["姉は建築家を志して勉強を始めた。","姐姐立志成为建筑师，开始学习。"],["この講座には翻訳を志す人も参加している。","这门课也有志在从事翻译的人参加。"]],"v-6cf73752-b061-11ef-b775-e7560ea47657":[["近所の反対が表立つ前に、話し合いが始まった。","在邻居公开反对前，商谈已经开始了。"],["彼は表立ってその案に反対しなかった。","他没有公开反对那项提案。"]],"v-b9dc014e-692e-11ef-95f0-b30e867324a9":[["火に近い壁だけが黒ずんでいた。","只有靠近火的那面墙发黑了。"],["古い銀の匙が黒ずんだので、柔らかい布で磨いた。","旧银勺发黑了，我用软布擦了擦。"]],"v-b9d9cee2-692e-11ef-95f0-b30e867324a9":[["砂糖を切らしたので、店に買いに行った。","糖用完了，我去店里买。"],["在庫を切らさないよう、残りを毎日数えた。","为了避免断货，我每天清点库存。"]],"v-0c0e2632-2ed7-11ef-a183-99ad05e145f0":[["箱は棚の奥にぴったり納まった。","盒子恰好放进了架子深处。"],["預かった写真は一冊のアルバムに納まった。","托我保管的照片都收进了一本相册。"]],"v-b9e65298-692e-11ef-95f0-b30e867324a9":[["村の人は水害の記憶を子どもに語り継いだ。","村里人把洪灾的记忆讲给孩子，代代传下去。"],["この祭りの由来は何世代にもわたって語り継がれてきた。","这项庆典的由来已经口口相传了好几代。"]],"v-b96f9824-692e-11ef-95f0-b30e867324a9":[["現物を前にすると、写真では分からなかった質感に気づいた。","看到实物后，我察觉到了照片里看不出的质感。"],["二つの試作品を並べ、質感の違いを確かめた。","我们把两个样品并排放置，核对了质感的差异。"]],"v-79fbab56-679e-11ef-89c9-3b0955f1365d":[["雪の上に白色の札を置くと、遠くから見えにくかった。","把白色牌子放在雪上，从远处很难看见。"],["赤い線の上から白色の絵の具を塗った。","我在红线之上涂了白色颜料。"]],"v-0cda26ec-2ed7-11ef-a183-99ad05e145f0":[["以前の手順に則って記録を整理した。","我们遵循以往的流程整理记录。"],["会の規則に則り、全員の意見を聞いた。","依照会议规则，我们听取了所有人的意见。"]],"v-0c5189ea-2ed7-11ef-a183-99ad05e145f0":[["その決定は新たな対立の種をはらんでいた。","那个决定孕育着新的对立。"],["雲は雨をはらんで重く垂れ込めていた。","云层带着雨水，沉沉地压下来。"]],"v-0c0a262c-2ed7-11ef-a183-99ad05e145f0":[["現地で地盤の状態を調べ、気づいたことを地図に書き込んだ。","我在现场调查地基，并把注意到的事情标在地图上。"],["季節が変わってから、地盤の様子をもう一度見に行った。","换季以后，我又去看了一次地基的情况。"]],"v-78490d82-4ce7-11f1-90a9-0fc8163987fc":[["お名前は以前から存じ上げております。","我早就听说过您的名字。"],["あの先生のことは存じ上げません。","我不认识那位老师。"]],"v-0c853d4e-2ed7-11ef-a183-99ad05e145f0":[["昔の資料には武家の様子が細かく書かれていた。","旧资料细致地写了武士家族的情况。"],["武家のことを祖父から聞き、覚えている話を記録した。","我听爷爷讲了武士家族，把记得的内容写下来。"]],"v-0c6b06ae-2ed7-11ef-a183-99ad05e145f0":[["二人の話し方はどこか似通っている。","两人的说话方式有些相似。"],["川沿いの家はどれも似通った造りだった。","沿河的房子构造都很相似。"]],"v-03a373f8-4ce9-11f1-90a9-0fc8163987fc":[["駅が移ってから、商店街は寂れた。","车站搬走后，商业街就萧条了。"],["寂れた港に、漁船が一隻だけ残っていた。","冷清的港口只剩一艘渔船。"]],"v-b9d895b8-692e-11ef-95f0-b30e867324a9":[["会議で移転を求める声が挙がった。","会上有人提出搬迁的要求。"],["予算を減らす案がいくつか挙がった。","有人提出了几个削减预算的方案。"]],"v-0ccad8b8-2ed7-11ef-a183-99ad05e145f0":[["彼女が手がけた展示を見に行った。","我去看了她操办的展览。"],["この工房は古い家具の修復も手がけている。","这个工坊也承接旧家具修复。"]],"v-0cd52390-2ed7-11ef-a183-99ad05e145f0":[["雨がやみ、空が晴れ渡った。","雨停了，天空彻底放晴。"],["晴れ渡った朝、遠くの山まで見えた。","晴朗的早晨，连远山也看得见。"]],"v-0c6fcd6a-2ed7-11ef-a183-99ad05e145f0":[["夜更かしは明日の仕事に障る。","熬夜会影响明天的工作。"],["強い照明は目に障るので、少し弱めた。","强光刺眼，我稍微调暗了。"]],"v-0c36de74-2ed7-11ef-a183-99ad05e145f0":[["世論の変化を調べるため、過去十年の記録を表にした。","为了考察舆论的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、世論にどのような傾向があるか説明した。","我们用调查结果解释了舆论有什么趋势。"]],"v-0ce80f0a-2ed7-11ef-a183-99ad05e145f0":[["氷が溶けて、飲み物の味が薄まった。","冰化了，饮料的味道变淡了。"],["話を聞いているうちに、最初の疑いが薄まった。","听着听着，起初的怀疑减弱了。"]],"v-b9e57daa-692e-11ef-95f0-b30e867324a9":[["葉をかたどった小皿を作った。","我做了个叶形小盘。"],["会場の入口には、船をかたどった門がある。","会场入口有一扇仿船造型的门。"]],"v-0bb0b326-2ed7-11ef-a183-99ad05e145f0":[["仕事を怠けて、締切に間に合わなかった。","干活偷懒，没赶上截止时间。"],["寒さを理由に運動を怠けた。","我拿天气冷当借口，偷懒没锻炼。"]],"v-0bd01b26-2ed7-11ef-a183-99ad05e145f0":[["道具を袋に入れて持ち運んだ。","我把工具放进袋里携带。"],["この机は分解すると楽に持ち運べる。","这张桌子拆开以后容易搬运。"]],"v-bff6fe0c-4d21-11f1-8acd-1921b1dbb6e1":[["短い旅行なら、小さなかばんで事足りる。","短途旅行用个小包就够了。"],["記録を読むだけなら、この画面で事足りる。","如果只看记录，这个屏幕就够用。"]],"v-0c112724-2ed7-11ef-a183-99ad05e145f0":[["文芸に興味を持ち、入門書を一冊選んだ。","我对文艺产生了兴趣，选了一本入门书。"],["公開講座で文芸について学び、以前とは違う見方をするようになった。","在公开课上学了文艺后，我开始有不同的看法。"]],"v-0cc5d3fe-2ed7-11ef-a183-99ad05e145f0":[["一度勝ったくらいで思い上がってはいけない。","不能只赢一次就自负。"],["褒められて思い上がり、人の助言を聞かなくなった。","受了夸奖就自大起来，不再听别人建议了。"]],"v-b94b861e-692e-11ef-95f0-b30e867324a9":[["現地で土壌の状態を調べ、気づいたことを地図に書き込んだ。","我在现场调查土壤，并把注意到的事情标在地图上。"],["季節が変わってから、土壌の様子をもう一度見に行った。","换季以后，我又去看了一次土壤的情况。"]],"v-b95504aa-692e-11ef-95f0-b30e867324a9":[["家に入る前に、間取りの位置を確認した。","进屋前，我确认了房屋布局的位置。"],["改修の前と後では、間取りが大きく変わった。","改修前后，房屋布局变化很大。"]],"v-b9d2ef50-692e-11ef-95f0-b30e867324a9":[["祖母は働きながら三人の子を育て上げた。","奶奶一边工作，一边把三个孩子养育成人。"],["植えた木を、十年かけて立派に育て上げた。","我花了十年，把种下的树培育得高大挺拔。"]],"v-b9d2b04e-692e-11ef-95f0-b30e867324a9":[["担当者がいるのに出しゃばってしまった。","明明有负责人，我却擅自插手了。"],["会議で出しゃばらず、まず皆の話を聞いた。","会上我没有抢着发言，先听大家怎么说。"]],"v-b95e4bfa-692e-11ef-95f0-b30e867324a9":[["現物を前にすると、写真では分からなかった肌触りに気づいた。","看到实物后，我察觉到了照片里看不出的触感。"],["二つの試作品を並べ、肌触りの違いを確かめた。","我们把两个样品并排放置，核对了触感的差异。"]],"v-0c52d796-2ed7-11ef-a183-99ad05e145f0":[["祖父はぼけないように、毎朝新聞を音読する。","爷爷每天早上朗读报纸，避免脑子变迟钝。"],["二日も寝込んで、頭が少しぼけたようだった。","我卧床两天，感觉脑子有点不灵光。"]],"v-b9d8121e-692e-11ef-95f0-b30e867324a9":[["住民の意見を聞いて計画を練り上げた。","听取居民意见后，我们仔细推敲了方案。"],["何度も直して、短い説明文を練り上げた。","我反复修改，打磨出一段简短的说明。"]],"v-0c378b80-2ed7-11ef-a183-99ad05e145f0":[["案内には、実際に寄せられた質問を盛り込んだ。","指引里纳入了实际收到的问题。"],["新しい契約に点検の項目を盛り込んだ。","新合同加入了检查条款。"]],"v-0cd95640-2ed7-11ef-a183-99ad05e145f0":[["住民は事業者を相手取って訴えを起こした。","居民以运营方为被告提起诉讼。"],["会社を相手取る裁判が翌月に始まった。","以该公司为被告的诉讼于次月开庭。"]],"v-6d182412-b061-11ef-b775-e7560ea47657":[["農家はビニールハウスで冬にも野菜を育てる。","农户在塑料大棚里冬天也种菜。"],["朝にハウスの入口を開けて、中の熱を逃がした。","早上我打开温室入口，让里面的热气散出去。"]],"v-0c509d78-2ed7-11ef-a183-99ad05e145f0":[["連休の駅前は買い物客でにぎわった。","连休时车站前购物的人很多，十分热闹。"],["祭りが始まり、ふだん静かな港がにぎわった。","庆典开始后，平时安静的港口热闹了起来。"]],"v-b97884de-692e-11ef-95f0-b30e867324a9":[["現物を前にすると、写真では分からなかった奥行きに気づいた。","看到实物后，我察觉到了照片里看不出的纵深感。"],["二つの試作品を並べ、奥行きの違いを確かめた。","我们把两个样品并排放置，核对了纵深感的差异。"]],"v-0bf4956e-2ed7-11ef-a183-99ad05e145f0":[["調べ始める前に、引力の意味を資料で確かめた。","开始调查前，我查阅材料确认了引力的含义。"],["説明では、引力について具体的な事例を挙げた。","讲解时，我们举了有关引力的具体例子。"]],"v-0bdab1b2-2ed7-11ef-a183-99ad05e145f0":[["糖分を少し増やしたら、前とは違う味になった。","稍微增加了糖分，味道就和以前不同了。"],["糖分がどのくらいあるか、作る前に確かめた。","制作前，我确认了糖分有多少。"]],"v-b9e28d84-692e-11ef-95f0-b30e867324a9":[["川沿いには白い花が咲き乱れていた。","河边白花盛开。"],["暖かくなると、野原に色とりどりの花が咲き乱れた。","天气暖起来，原野上各色花朵竞相开放。"]],"v-0c0e8028-2ed7-11ef-a183-99ad05e145f0":[["封筒から古い切手を丁寧に剝がした。","我小心地把旧邮票从信封上揭下来。"],["塗り直す前に、浮いた塗料を剝がした。","重新上漆前，我铲掉了翘起的旧漆。"]],"v-b9e575b2-692e-11ef-95f0-b30e867324a9":[["細い道の片側には崖が切り立っていた。","窄路一侧耸立着陡峭的崖壁。"],["船からは切り立った岩山が見えた。","从船上能看到陡立的岩山。"]],"v-7a2f08ac-679e-11ef-89c9-3b0955f1365d":[["荷物を欲張って詰めると、箱が閉まらない。","贪多往里塞东西，盒子就关不上。"],["全部食べようと欲張ったせいで、後で苦しくなった。","因为贪心想吃光，后来撑得难受。"]],"v-0c32e09e-2ed7-11ef-a183-99ad05e145f0":[["忘れないよう、駅員の説明を書き留めた。","为了不忘，我记下了车站工作人员的说明。"],["家に着いてから、その日に聞いた話を書き留めた。","到家后，我把那天听到的话记了下来。"]],"v-0cc41956-2ed7-11ef-a183-99ad05e145f0":[["毎日使うかばんの持ち手が擦り切れた。","每天用的包提手磨破了。"],["袖口が擦り切れるまで、その上着を着続けた。","我一直穿那件外套，直到袖口磨破。"]],"v-b97b64ba-692e-11ef-95f0-b30e867324a9":[["白木を濡らさないよう、箱に入れてから運んだ。","我把原木装进盒子才搬运，免得弄湿。"],["棚から古い白木を取り出し、別の場所へ移した。","我从架子上取下旧的原木，移到了别处。"]],"v-b98003a8-692e-11ef-95f0-b30e867324a9":[["製薬に興味を持ち、入門書を一冊選んだ。","我对制药产生了兴趣，选了一本入门书。"],["公開講座で製薬について学び、以前とは違う見方をするようになった。","在公开课上学了制药后，我开始有不同的看法。"]],"v-0c3cd7fc-2ed7-11ef-a183-99ad05e145f0":[["申込みは予想を超した。","报名人数超过了预期。"],["朝から気温が三十度を超していた。","从早上起气温就超过了三十度。"]],"v-0cca40b0-2ed7-11ef-a183-99ad05e145f0":[["強風のため、屋外の演奏会を取りやめた。","由于风大，取消了户外音乐会。"],["夜の移動は危ないので取りやめることにした。","夜里出行危险，我们决定取消。"]],"v-90abfa4e-4d26-11f1-8acd-1921b1dbb6e1":[["猫が足に擦り寄ってきた。","猫凑到我脚边蹭了蹭。"],["子犬は寒そうに母犬へ擦り寄った。","小狗似乎冷了，紧贴到狗妈妈身边。"]],"v-078fe724-d988-11ef-bb43-2f0a9df7a5d2":[["指標の変化を調べるため、過去十年の記録を表にした。","为了考察指标的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、指標にどのような傾向があるか説明した。","我们用调查结果解释了指标有什么趋势。"]],"v-0c5b6c30-2ed7-11ef-a183-99ad05e145f0":[["朝の静かなうちに街頭へ向かった。","趁早上安静，我朝街头出发。"],["撮影した写真を見返すと、夕方の街頭は朝とは違って見えた。","回看照片时，我发现傍晚的街头看起来与清晨不同。"]],"v-0c80d372-57bb-11f0-a71e-995f04a60375":[["返事もせず帰った彼に、皆が呆れ果てた。","他没回答就走了，大家对他无语透了。"],["同じ間違いを繰り返す自分に呆れ果てた。","我反复犯同样的错，对自己也无语透了。"]],"v-0cfa1074-2ed7-11ef-a183-99ad05e145f0":[["工事が野鳥の生息地を脅かしている。","施工正在威胁野鸟的栖息地。"],["長引く停電は、地域の暮らしを脅かした。","持续停电威胁到了当地居民的生活。"]],"v-0ba9892a-2ed7-11ef-a183-99ad05e145f0":[["祝日の日には、家族でいつもと違う料理を作った。","法定节日那天，全家做了和平时不同的菜。"],["町の行事が祝日と重なり、日程を少しずらした。","镇里的活动赶上了法定节日，于是稍稍调整了日期。"]],"v-b9e352c8-692e-11ef-95f0-b30e867324a9":[["選手たちは厳しい練習に耐え抜いた。","选手们熬过了艰苦的训练。"],["風を避けられる場所で、寒い夜を耐え抜いた。","我在能避风的地方熬过了寒夜。"]],"v-b9d82178-692e-11ef-95f0-b30e867324a9":[["箱のふたには小さな石がちりばめられていた。","盒盖上镶嵌着小石头。"],["作者は物語の各所に手がかりをちりばめた。","作者把线索分散埋在故事各处。"]],"v-49d72624-b061-11ef-b775-e7560ea47657":[["現地で堰の状態を調べ、気づいたことを地図に書き込んだ。","我在现场调查拦河堰，并把注意到的事情标在地图上。"],["季節が変わってから、堰の様子をもう一度見に行った。","换季以后，我又去看了一次拦河堰的情况。"]],"v-b9e3f05c-692e-11ef-95f0-b30e867324a9":[["耳慣れた声が改札の向こうから聞こえた。","检票口另一边传来一个熟悉的声音。"],["最初は難しくても、毎日聞くと耳慣れてくる。","即使起初觉得难，每天听就会逐渐听惯。"]],"v-0b868b14-2ed7-11ef-a183-99ad05e145f0":[["朝の静かなうちに島々へ向かった。","趁早上安静，我朝岛屿出发。"],["撮影した写真を見返すと、夕方の島々は朝とは違って見えた。","回看照片时，我发现傍晚的岛屿看起来与清晨不同。"]],"v-0c41d69e-2ed7-11ef-a183-99ad05e145f0":[["不況の変化を調べるため、過去十年の記録を表にした。","为了考察经济不景气的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、不況にどのような傾向があるか説明した。","我们用调查结果解释了经济不景气有什么趋势。"]],"v-6d40ac48-b061-11ef-b775-e7560ea47657":[["祖父は時間をかけて荒い馬を手なずけた。","爷爷花了很长时间才驯服那匹烈马。"],["物語の子どもは野犬を手なずけ、旅の仲間にした。","故事里的孩子驯服了野狗，让它成了旅伴。"]],"v-0ce6e030-2ed7-11ef-a183-99ad05e145f0":[["納期の記録は、日付が分かるように整理した。","我们把交付期限的记录按能辨明日期的方式整理了。"],["後から納期を確認するため、関係する資料を残した。","为了以后能核实交付期限，我们留下了相关材料。"]],"v-7a598dc0-679e-11ef-89c9-3b0955f1365d":[["庭をほったらかしたら草だらけになった。","院子丢着不管，长满了杂草。"],["濡れた靴をほったらかすと傷むよ。","湿鞋一直不管会坏的。"]],"v-0bce40a8-2ed7-11ef-a183-99ad05e145f0":[["数年分を並べて、黒字がどう変わったか比べた。","我把好几年的数据排在一起，比较盈余如何变化。"],["会議で黒字を確認し、次の予定を決めた。","会上确认了盈余，随后定下下一项安排。"]],"v-0c175414-2ed7-11ef-a183-99ad05e145f0":[["祭りの夜、広場では人々の声が飛び交った。","庆典当晚，广场上人声交错。"],["会議では厳しい言葉が行き交った。","会上你一言我一语，言辞激烈。"]],"v-7a5b4a34-679e-11ef-89c9-3b0955f1365d":[["調べ始める前に、哺乳類の意味を資料で確かめた。","开始调查前，我查阅材料确认了哺乳类的含义。"],["説明では、哺乳類について具体的な事例を挙げた。","讲解时，我们举了有关哺乳类的具体例子。"]],"v-0bebaeae-2ed7-11ef-a183-99ad05e145f0":[["通れるように、入口の箱をどけた。","我把入口的箱子挪开，让人能通过。"],["椅子をどけて、床の傷を見た。","我挪开椅子查看地板上的划痕。"]],"v-0c2a08fc-2ed7-11ef-a183-99ad05e145f0":[["月刊には、祖母が小さいころの町の写真が載っていた。","月刊刊登了奶奶小时候镇上的照片。"],["閉館前に月刊を取り出し、必要なページを写した。","闭馆前，我取出月刊，抄了需要的页面。"]],"v-39ac2460-4df0-11f1-92ad-a9d8dc6c1b5c":[["発車前のホームは人で溢れ返っていた。","发车前的站台挤满了人。"],["大雨で排水溝から水が溢れ返った。","暴雨导致排水沟里的水漫了出来。"]],"v-8a08c8b4-4df0-11f1-92ad-a9d8dc6c1b5c":[["彼女は地図を描く速さで仲間から抜きん出ていた。","她画地图的速度远超同伴。"],["その品は耐久性の点で抜きん出ている。","那件产品在耐用性上尤为出色。"]],"v-0ca4c5f6-2ed7-11ef-a183-99ad05e145f0":[["皆でラグビーの面白さについて話した。","大家聊了橄榄球有意思的地方。"],["ラグビーに関する展示を見て、今まで知らなかったことを一つ覚えた。","看了有关橄榄球的展览，我记住了一件从前不知道的事。"]],"v-0c3eb4be-2ed7-11ef-a183-99ad05e145f0":[["会場には特産が置かれ、実際に手に取ることができた。","会场摆着特产，人们可以亲手拿起来看。"],["持ち帰った特産を家族に見せ、どこで見つけたか説明した。","我把带回来的特产给家人看，讲了是在哪儿发现的。"]],"v-b987ddb2-692e-11ef-95f0-b30e867324a9":[["見学者は展示された骨董の表面をよく観察した。","参观者仔细观察了展出的古董的表面。"],["製作者は、骨董を作った時期と材料を記録していた。","制作者记下了制作古董的时间与材料。"]],"v-0c6167ca-2ed7-11ef-a183-99ad05e145f0":[["忙しい店の責任者が私に勤まるだろうか。","那么忙的店，让我来负责能胜任吗？"],["慣れるまでは、一人で受付は勤まらない。","熟悉之前，还不能独立做接待工作。"]],"v-b9d45836-692e-11ef-95f0-b30e867324a9":[["結論が出ないので、最初の問いに立ち戻った。","得不出结论，我就回到最初的问题。"],["意見が割れたら、目的に立ち戻って考えよう。","意见分歧时，回到原先的目的重新想吧。"]],"v-0ce7739c-2ed7-11ef-a183-99ad05e145f0":[["廃棄物の記録は、日付が分かるように整理した。","我们把废弃物的记录按能辨明日期的方式整理了。"],["後から廃棄物を確認するため、関係する資料を残した。","为了以后能核实废弃物，我们留下了相关材料。"]],"v-0bf3b388-2ed7-11ef-a183-99ad05e145f0":[["為替の変化を調べるため、過去十年の記録を表にした。","为了考察汇率的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、為替にどのような傾向があるか説明した。","我们用调查结果解释了汇率有什么趋势。"]],"v-b9794a7c-692e-11ef-95f0-b30e867324a9":[["師走が迫り、店は準備で慌ただしくなった。","十二月临近，店里忙着做准备。"],["家族と話し合い、旅行は師走にしようと決めた。","和家人商量后，我们决定把旅行安排在十二月。"]],"v-88248ebe-4e79-11f1-beee-f9338ab5b368":[["小さな変更でも、画質に影響が出ないか先に確かめた。","即使是小变动，我们也先确认会不会影响画质。"],["実際に使った人から、画質について意見を聞いた。","我们向实际使用者征求了对画质的意见。"]],"v-b9e5853e-692e-11ef-95f0-b30e867324a9":[["青と白の糸が細かな模様を織り成していた。","蓝线和白线交织成细密的花样。"],["川と畑が織り成す風景を、丘の上から眺めた。","我在丘顶眺望河流与田野交织成的景色。"]],"v-0c7a1540-2ed7-11ef-a183-99ad05e145f0":[["畜産に興味を持ち、入門書を一冊選んだ。","我对畜牧业产生了兴趣，选了一本入门书。"],["公開講座で畜産について学び、以前とは違う見方をするようになった。","在公开课上学了畜牧业后，我开始有不同的看法。"]],"v-b9df32a6-692e-11ef-95f0-b30e867324a9":[["巣に近づくと、鳥が上から襲いかかってきた。","一靠近鸟巢，鸟就从上方扑了过来。"],["暗がりから何者かが旅人に襲いかかった。","有人从暗处突然袭击了旅人。"]],"v-7d583112-ce68-11ef-9903-4d5df4b0073e":[["調べ始める前に、形質の意味を資料で確かめた。","开始调查前，我查阅材料确认了性状的含义。"],["説明では、形質について具体的な事例を挙げた。","讲解时，我们举了有关性状的具体例子。"]],"v-0c4a568e-2ed7-11ef-a183-99ad05e145f0":[["厚い毛布はかばんの中で嵩張る。","厚毯子在包里很占地方。"],["空箱が嵩張ったので、つぶして運んだ。","空盒子太占地方，我把它压扁后再搬。"]],"v-4a6533b0-b061-11ef-b775-e7560ea47657":[["この装置は、可視光だけを通す。","这台装置只让可见光通过。"],["調査の結果を可視化すると、地区による差がよく分かった。","把调查结果可视化后，各地区间的差别清楚多了。"]],"v-0c95f8a0-2ed7-11ef-a183-99ad05e145f0":[["会場の係に、クーポンを受け取る場所を尋ねた。","我问会场工作人员到哪儿领优惠券。"],["帰宅してから、クーポンを家族にも見せた。","回家后，我也给家人看了优惠券。"]],"v-b96f87ee-692e-11ef-95f0-b30e867324a9":[["夏至の日には、家族でいつもと違う料理を作った。","夏至那天，全家做了和平时不同的菜。"],["町の行事が夏至と重なり、日程を少しずらした。","镇里的活动赶上了夏至，于是稍稍调整了日期。"]],"v-b96f7df8-692e-11ef-95f0-b30e867324a9":[["冬至の日には、家族でいつもと違う料理を作った。","冬至那天，全家做了和平时不同的菜。"],["町の行事が冬至と重なり、日程を少しずらした。","镇里的活动赶上了冬至，于是稍稍调整了日期。"]],"v-7d58da7c-ce68-11ef-9903-4d5df4b0073e":[["情報公開についての問い合わせを、担当窓口で受け付けた。","办事窗口受理了有关信息公开的咨询。"],["情報公開の手続きがどのように変わったか、案内を読んだ。","我读了指引，了解信息公开的手续有何变化。"]],"v-b9dd072e-692e-11ef-95f0-b30e867324a9":[["地元の漁師はこの海の癖を知り抜いている。","当地渔民深知这片海的特点。"],["古い家を知り抜いた祖父に、配管の場所を聞いた。","我向对老房子了如指掌的爷爷问了管道的位置。"]],"v-7d58ed28-ce68-11ef-9903-4d5df4b0073e":[["農林に興味を持ち、入門書を一冊選んだ。","我对农业和林业产生了兴趣，选了一本入门书。"],["公開講座で農林について学び、以前とは違う見方をするようになった。","在公开课上学了农业和林业后，我开始有不同的看法。"]],"v-0c248d28-2ed7-11ef-a183-99ad05e145f0":[["過疎の変化を調べるため、過去十年の記録を表にした。","为了考察人口稀疏的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、過疎にどのような傾向があるか説明した。","我们用调查结果解释了人口稀疏有什么趋势。"]],"v-7aaf9f62-679e-11ef-89c9-3b0955f1365d":[["社会保障についての問い合わせを、担当窓口で受け付けた。","办事窗口受理了有关社会保障的咨询。"],["社会保障の手続きがどのように変わったか、案内を読んだ。","我读了指引，了解社会保障的手续有何变化。"]],"v-0cedc2b0-2ed7-11ef-a183-99ad05e145f0":[["港で珍しい魚が揚がったと聞きつけて出かけた。","一听说港口捕上了罕见的鱼，我就赶去了。"],["物音を聞きつけ、犬が玄関へ走った。","狗听到响动，跑去了门厅。"]],"v-6dc93d56-b061-11ef-b775-e7560ea47657":[["見学者は展示された水墨画の表面をよく観察した。","参观者仔细观察了展出的水墨画的表面。"],["製作者は、水墨画を作った時期と材料を記録していた。","制作者记下了制作水墨画的时间与材料。"]],"v-b965adc8-692e-11ef-95f0-b30e867324a9":[["調べ始める前に、表面張力の意味を資料で確かめた。","开始调查前，我查阅材料确认了表面张力的含义。"],["説明では、表面張力について具体的な事例を挙げた。","讲解时，我们举了有关表面张力的具体例子。"]],"v-b9e92f5e-692e-11ef-95f0-b30e867324a9":[["水不足で庭の木が痩せ衰えた。","由于缺水，院里的树逐渐枯瘦。"],["長い病気のあと、彼は痩せ衰えて歩くのも難しかった。","久病之后，他消瘦衰弱，连走路都困难。"]],"v-890f7ea6-4e79-11f1-beee-f9338ab5b368":[["見学者は展示された小品の表面をよく観察した。","参观者仔细观察了展出的小幅作品的表面。"],["製作者は、小品を作った時期と材料を記録していた。","制作者记下了制作小幅作品的时间与材料。"]],"v-0bc1e97a-2ed7-11ef-a183-99ad05e145f0":[["調べ始める前に、サイエンスの意味を資料で確かめた。","开始调查前，我查阅材料确认了科学的含义。"],["説明では、サイエンスについて具体的な事例を挙げた。","讲解时，我们举了有关科学的具体例子。"]],"v-890d833a-4e79-11f1-beee-f9338ab5b368":[["調べ始める前に、クオリアの意味を資料で確かめた。","开始调查前，我查阅材料确认了感质的含义。"],["説明では、クオリアについて具体的な事例を挙げた。","讲解时，我们举了有关感质的具体例子。"]],"v-b9853814-692e-11ef-95f0-b30e867324a9":[["デフレの変化を調べるため、過去十年の記録を表にした。","为了考察通货紧缩的变化，我们把过去十年的记录做成表格。"],["調査の結果を使い、デフレにどのような傾向があるか説明した。","我们用调查结果解释了通货紧缩有什么趋势。"]],"v-890dab6c-4e79-11f1-beee-f9338ab5b368":[["調べ始める前に、ジェンダーの意味を資料で確かめた。","开始调查前，我查阅材料确认了社会性别的含义。"],["説明では、ジェンダーについて具体的な事例を挙げた。","讲解时，我们举了有关社会性别的具体例子。"]],"v-7a4f7538-679e-11ef-89c9-3b0955f1365d":[["新しい橋は地元の鳥にちなんで名づけられた。","新桥借当地一种鸟命名。"],["祭りにちなんだ色で店の窓を飾った。","店铺用与庆典有关的颜色装饰了窗户。"]],"v-b9d40b4c-692e-11ef-95f0-b30e867324a9":[["実際の費用は、当初の見積もりとかけ離れていた。","实际费用与最初的估价相差悬殊。"],["二つの村は互いにかけ離れた場所にある。","两个村庄相距甚远。"]],"v-b9d96a74-692e-11ef-95f0-b30e867324a9":[["この瓶は真ん中がくびれていて持ちやすい。","这个瓶子中间收窄，容易拿握。"],["島の地形は中央が細くくびれている。","岛的地形在中央变窄。"]],"v-0ce1df40-2ed7-11ef-a183-99ad05e145f0":[["彼女は練習を重ねて、ついに夢を適えた。","她反复练习，终于实现了梦想。"],["新しい制度は、利用者の願いを適えるために作った。","新制度是为实现使用者的愿望而制定的。"]],"v-b9d9f4da-692e-11ef-95f0-b30e867324a9":[["板が車の後ろから少しはみ出していた。","板子从车尾伸出了一点。"],["定められた枠からはみ出さないように文字を書いた。","我写字时尽量没有超出指定方框。"]]};
 for (const word of window.VOCAB) {
  if (Object.prototype.hasOwnProperty.call(examples, word.id)) {
   word.examples.push(...examples[word.id]);
  }
 }
})();
